/* FMGE question bank v1 — 300 questions, options, subject/type mapping. Answer keys are NOT in this file (see review.js). */
window.FMGE_BANK={"id":"fmge-sample-paper-1","version":1,"count":300,"source":{"name":"FMGE Sample Paper 1 (Collegedunia)","url":"https://image-static.collegedunia.com/public/image/1787253753_FMGE_Sample_Paper_1.pdf"},"questions":[{"n":1,"stem":"A 42-year-old construction worker presents with pain and paraesthesia along the medial aspect of his forearm and the medial one-and-a-half fingers of the right hand following a crush injury to the upper limb. Sensory testing confirms loss of light touch in that distribution. Which nerve root level is MOST likely responsible for this dermatomal pattern?","options":{"A":"C8–T1","B":"C6–C7","C":"C5–C6","D":"T2–T3"},"page":0,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":2,"stem":"A 29-year-old woman undergoes a lymph node biopsy in the posterior triangle of the neck. Two weeks post-operatively she is unable to abduct her right shoulder beyond 90° and the scapula wings when she pushes against a wall. Which nerve was MOST likely injured during the procedure?","options":{"A":"Phrenic nerve","B":"Accessory nerve (CN XI)","C":"Greater auricular nerve","D":"Dorsal scapular nerve"},"page":1,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":3,"stem":"A 25-year-old motorcyclist is brought to the emergency department after a high-speed collision. He has complete sensory and motor loss in the entire upper limb on the left side. Imaging shows avulsion of nerve roots. The diagram below represents the brachial plexus. C5 C6 C7 C8 T1 Upper Middle Lower Lateral Posterior Medial X The point marked X indicates avulsion of which trunk, and which named terminal branches originate exclusively from the roots contributing to this trunk?","options":{"A":"Lower trunk; medial pectoral and medial cutaneous nerves of arm and forearm","B":"Upper trunk; suprascapular and nerve to subclavius","C":"Middle trunk; no named branches arise exclusively from it","D":"Lower trunk; long thoracic and dorsal scapular nerves"},"page":1,"subject":"Anatomy","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":4,"stem":"A 67-year-old hypertensive man is brought unconscious to the emergency room. CT scan reveals a haemorrhage in the territory of the lenticulostriate arteries. Which major cerebral artery gives rise to these perforating vessels?","options":{"A":"Posterior cerebral artery","B":"Anterior cerebral artery","C":"Middle cerebral artery","D":"Basilar artery"},"page":2,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":5,"stem":"During a cadaveric dissection, a student identifies the artery running in the posterior interventricular groove. Occlusion of this vessel MOST commonly leads to infarction of which region?","options":{"A":"Anterior wall of right ventricle","B":"Lateral wall of left ventricle","C":"Anterior two-thirds of the interventricular septum","D":"Posterior one-third of the interventricular septum and posterior wall of the left ventricle"},"page":2,"subject":"Anatomy","kind":"Concept / direct recall","section":"Pre-clinical"},{"n":6,"stem":"A 45-year-old patient undergoing elective nephrectomy is found to have a polar renal artery arising directly from the aorta supplying the upper pole of the left kidney. The surgeon inadvertently ligates this vessel. Which of the following statements about renal segmental arteries is MOST accurate?","options":{"A":"They are end-arteries; ligation causes infarction of the corresponding segment","B":"They anastomose freely at the cortex, so ligation is inconsequential","C":"They run only in the renal sinus, not entering the parenchyma","D":"They arise exclusively from the renal vein tributaries"},"page":2,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":7,"stem":"A 55-year-old man presents with a band-like burning pain around his trunk at the level of the umbilicus following a herpes zoster eruption. The diagram below shows a schematic of the spinal column with vertebral levels marked. C1 C5 C8 T1 T4 T6 T8 T10 T12 L1 L4 S1 ? The arrow marked ? points to the spinal level that MOST likely corresponds to the dermatomal level of the umbilicus. Which level is this?","options":{"A":"T6","B":"T8","C":"T10","D":"T12"},"page":2,"subject":"Anatomy","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":8,"stem":"A 20-year-old rugby player sustains a severe direct blow to the lateral aspect of his right leg. Four hours later he complains of excruciating pain in the leg that is disproportionate to the injury and worsens on passive dorsiflexion of the toes. Compartment syndrome is suspected. Which compartment of the leg contains the deep peroneal nerve and the anterior tibial artery?","options":{"A":"Lateral compartment","B":"Anterior compartment","C":"Superficial posterior compartment","D":"Deep posterior compartment"},"page":3,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":9,"stem":"A 52-year-old woman is diagnosed with carcinoma of the lateral quadrant of her right breast. During staging workup, sentinel lymph node biopsy is planned. To which group of lymph nodes does MOST (approximately 75%) of the lymphatic drainage of the breast primarily drain?","options":{"A":"Internal mammary (parasternal) nodes","B":"Supraclavicular nodes","C":"Deltopectoral (infraclavicular) nodes","D":"Anterior (pectoral) axillary nodes"},"page":3,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":10,"stem":"A 78-year-old woman sustains a displaced intracapsular fracture of the neck of the femur after a fall. Her orthopaedic surgeon explains that avascular necrosis of the femoral head is a major complication. The primary blood supply to the adult femoral head is derived from which source?","options":{"A":"Retinacular branches of the medial circumflex femoral artery","B":"Obturator artery via the ligamentum teres","C":"Lateral circumflex femoral artery","D":"Inferior gluteal artery"},"page":4,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":11,"stem":"A 34-year-old man presents with loss of pain and temperature sensation on the right side of the body below T6, and loss of fine touch and proprioception on the left side below T6, following a penetrating injury. The diagram below represents a transverse section of the spinal cord. Dorsal Ventral DC ALS DC ALS L DC = dorsal columns; ALS = anterolateral system; L = lesion site. This injury pattern is MOST consistent with which syndrome?","options":{"A":"Central cord syndrome","B":"Anterior cord syndrome","C":"Brown-Séquard syndrome","D":"Posterior cord syndrome"},"page":4,"subject":"Anatomy","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":12,"stem":"A 60-year-old man presents with a groin swelling that appears medial to the inferior epigastric vessels and passes through the superficial inguinal ring. It is reducible and has an expansile cough impulse. Which of the following best describes this hernia?","options":{"A":"Indirect inguinal hernia passing through the deep inguinal ring lateral to the inferior epigastric vessels","B":"Femoral hernia passing through the femoral canal below the inguinal ligament","C":"Spigelian hernia through the linea semilunaris","D":"Direct inguinal hernia through Hesselbach’s triangle"},"page":5,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":13,"stem":"A 35-year-old patient with a base of skull fracture has clinical signs of a lesion at the jugular foramen. Which combination of cranial nerves would MOST likely be affected?","options":{"A":"CN IX, CN X, CN XI","B":"CN III, CN IV, CN VI","C":"CN V1, CN V2, CN VI","D":"CN VII, CN VIII"},"page":5,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":14,"stem":"A neonate is found to have malrotation of the midgut during exploratory laparotomy for volvulus. During normal embryological development, the physiological herniation of the midgut through the umbilical ring occurs in the SIXTH week. When the gut returns to the abdominal cavity, it undergoes counterclockwise rotation of how many degrees (as viewed from the front)?","options":{"A":"90°","B":"270°","C":"180°","D":"360°"},"page":5,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":15,"stem":"A pathology resident is examining a renal biopsy specimen under light microscopy. She identifies tall columnar cells with a brush border, abundant mitochondria, and no visible lumen in cross-section due to complex interdigitating basolateral processes. These features are MOST characteristic of which segment of the nephron?","options":{"A":"Collecting duct","B":"Descending thin limb of loop of Henle","C":"Proximal convoluted tubule","D":"Glomerular parietal epithelium"},"page":6,"subject":"Anatomy","kind":"Concept / direct recall","section":"Pre-clinical"},{"n":16,"stem":"A 48-year-old man with cirrhosis develops haematemesis. Upper GI endoscopy reveals oesophageal varices at the lower end of the oesophagus. This is due to a portal-systemic anastomosis between the left gastric (portal) and the oesophageal tributaries of the azygos vein (systemic). Which additional site of clinically important porto-systemic anastomosis can produce caput medusae?","options":{"A":"Lower rectum between superior and inferior rectal veins","B":"Bare area of liver between portal tributaries and phrenic veins","C":"Retroperitoneum via veins of Retzius","D":"Para-umbilical veins (portal) anastomosing with superficial epigastric veins (systemic) at the falciform ligament"},"page":6,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":17,"stem":"A 40-year-old man develops sudden onset of complete unilateral facial weakness involving the forehead, eye, cheek, and mouth on the right side following a viral illness. He cannot close his right eye and has hyperacusis. Which of the following BEST explains the hyperacusis in this patient?","options":{"A":"Loss of the greater petrosal nerve branch affecting the lacrimal gland","B":"Paralysis of stapedius muscle, which normally damps loud sounds","C":"Damage to the chorda tympani reducing taste on the anterior twothirds of the tongue","D":"Involvement of the auriculotemporal branch of the mandibular nerve"},"page":6,"subject":"Anatomy","kind":"Clinical vignette","section":"Pre-clinical"},{"n":18,"stem":"A physiology student is studying a neuronal action potential trace obtained by intracellular recording. The diagram below shows the voltage change over time, with five labelled phases. Time (ms) Vm (mV) I II III IV V threshold −70 mV During phase III (the peak of the action potential), which ion channel state and ion movement BEST describe the membrane condition?","options":{"A":"Voltage-gated Na+ channels open; rapid Na+ influx drives the membrane to +30 to +40 mV","B":"Voltage-gated K+ channels open; K+ efflux causes repolarisation","C":"Na+–K+ ATPase actively pumps Na+ out; restoring resting potential","D":"Voltage-gated Na+ channels are inactivated; membrane is in absolute refractory period"},"page":7,"subject":"Physiology","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":19,"stem":"A pharmacology researcher applies a drug that selectively blocks voltagegated K+ channels at rest in a cardiac myocyte. Which of the following BEST describes the immediate effect on the resting membrane potential (RMP)?","options":{"A":"RMP becomes more negative (hyperpolarisation) because Na+ influx increases","B":"RMP becomes less negative (depolarisation) because the outward K+ current maintaining RMP is lost","C":"RMP remains unchanged because the Na+–K+ ATPase compensates immediately","D":"RMP becomes more negative due to increased Cl−conductance"},"page":7,"subject":"Physiology","kind":"Concept / direct recall","section":"Pre-clinical"},{"n":20,"stem":"A 30-year-old medical student is interpreting a Wiggers diagram in a physiology exam. He notes that at the moment the mitral valve closes, the aortic valve is also closed and the left ventricular pressure is rising rapidly. Which phase of the cardiac cycle does this describe?","options":{"A":"Rapid ventricular filling","B":"Isovolumetric relaxation","C":"Isovolumetric contraction","D":"Rapid ejection"},"page":8,"subject":"Physiology","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":21,"stem":"During a cardiac catheterisation study in a 55-year-old woman, the following values are recorded: O2 consumption = 250 mL/min; pulmonary artery O2 content = 150 mL/L; pulmonary vein O2 content = 200 mL/L. Using the Fick principle, what is the cardiac output?","options":{"A":"3.5 L/min","B":"4.0 L/min","C":"4.5 L/min","D":"5.0 L/min"},"page":8,"subject":"Physiology","kind":"Clinical vignette","section":"Pre-clinical"},{"n":22,"stem":"The diagram below shows a left ventricular pressure-volume (PV) loop for a healthy adult at rest. Four corners are labelled 1–4. Volume (mL) Pressure (mmHg) ESPVR The segment from point 2 to point 3 represents which phase, and which valves are open at this time?","options":{"A":"Isovolumetric contraction; both mitral and aortic valves closed","B":"Rapid ejection; aortic valve open, mitral valve closed","C":"Isovolumetric relaxation; both valves closed","D":"Rapid ventricular filling; mitral open, aortic closed"},"page":8,"subject":"Physiology","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":23,"stem":"A 65-year-old long-term smoker performs spirometry. The trace below shows a schematic tidal and forced breathing manoeuvre with lung volumes labelled. Time Volume (L) TLC IRV top EEL (FRC) RV TV ERV IRV In a patient with obstructive lung disease, which combination of spirometric values is MOST characteristic?","options":{"A":"Decreased TLC, decreased FRC, normal RV","B":"Decreased FEV1/FVC ratio with decreased TLC","C":"Decreased FEV1/FVC ratio with increased RV and FRC (air trapping)","D":"Normal FEV1/FVC ratio with decreased FVC and decreased TLC"},"page":9,"subject":"Physiology","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":24,"stem":"A 50-year-old hypertensive patient is started on an ACE inhibitor. His serum creatinine rises modestly. The mechanism of GFR maintenance in the kidney involves myogenic autoregulation and tubuloglomerular feedback. Which of the following BEST explains the rise in creatinine in this patient on ACE inhibition?","options":{"A":"Afferent arteriolar vasoconstriction reduces renal plasma flow","B":"Efferent arteriolar dilation reduces glomerular hydrostatic pressure and therefore GFR","C":"Increased aldosterone causes sodium retention, expanding plasma volume and diluting creatinine","D":"Mesangial cell contraction reduces filtration surface area in response to elevated angiotensin II"},"page":10,"subject":"Physiology","kind":"Clinical vignette","section":"Pre-clinical"},{"n":25,"stem":"A 22-year-old woman presents with glycosuria but a fasting blood glucose of 5.2 mmol/L (normal). Urine glucose is consistently positive. Genetic testing confirms a mutation in the SGLT2 transporter in the proximal tubule. Which physiological concept BEST explains why glucose normally does not appear in the urine up to a plasma glucose of approximately 180 mg/dL?","options":{"A":"Glucose is freely filtered but entirely reabsorbed by passive diffusion in the loop of Henle","B":"Glucose reabsorption is driven solely by the concentration gradient with no transporter involvement","C":"The tubular transport maximum (Tm) for glucose is not exceeded below approximately 180 mg/dL; all filtered glucose is reabsorbed","D":"The glomerular basement membrane is impermeable to glucose below 180 mg/dL"},"page":10,"subject":"Physiology","kind":"Clinical vignette","section":"Pre-clinical"},{"n":26,"stem":"A 3-day-old neonate is noted to be jaundiced. Total serum bilirubin is 15 mg/dL, predominantly unconjugated. The neonate is feeding well and has no haemolysis. Which enzyme is responsible for conjugating bilirubin to bilirubin glucuronide in hepatocytes, and why is its activity transiently reduced in neonatal physiological jaundice?","options":{"A":"Biliverdin reductase; reduced due to low haem oxygenase activity","B":"Alanine aminotransferase; reduced due to immature hepatic blood flow","C":"Alkaline phosphatase; reduced because the canalicular membrane is underdeveloped","D":"UDP-glucuronosyltransferase (UGT1A1); transiently low expression in the neonatal liver"},"page":11,"subject":"Physiology","kind":"Concept / direct recall","section":"Pre-clinical"},{"n":27,"stem":"A 28-year-old woman is being investigated for infertility. Her menstrual cycle is 28 days. A urine LH kit detects a surge on day 13. Which of the following BEST describes the hormonal event that triggers the LH surge?","options":{"A":"Rising oestradiol from the dominant follicle switches the hypothalamopituitary axis from negative to positive feedback, triggering GnRH pulse amplification and the LH surge","B":"A sudden fall in progesterone from the corpus luteum removes negative feedback, allowing FSH to surge","C":"Rising inhibin B from granulosa cells directly stimulates pituitary LH release","D":"A rise in prolactin from the anterior pituitary stimulates ovarian LH receptors to trigger ovulation"},"page":11,"subject":"Physiology","kind":"Clinical vignette","section":"Pre-clinical"},{"n":28,"stem":"The diagram below shows Frank-Starling curves for the heart under different conditions. EDV / Preload Stroke Volume Normal X Y ↑SV Curve X is shifted upward relative to the normal curve. Which physiological or pharmacological state BEST explains this shift?","options":{"A":"Administration of a beta-blocker reducing heart rate and contractility","B":"Administration of dobutamine, a positive inotrope increasing myocardial contractility","C":"Acute haemorrhage reducing venous return and preload","D":"Cardiac tamponade limiting ventricular filling"},"page":11,"subject":"Physiology","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":29,"stem":"A 22-year-old male marathon runner collapses at the finish line. His rectal temperature is 40.5°C. In the normal temperature regulation response to hyperthermia, which of the following CORRECTLY describes the effector responses coordinated by the hypothalamic thermostat?","options":{"A":"Cutaneous vasoconstriction to conserve heat; piloerection; shivering thermogenesis","B":"Reduced metabolic rate in skeletal muscle; increased GI absorption of water","C":"Cutaneous vasodilation; increased sweating; reduced skeletal muscle tone","D":"Increased ADH release to reduce urinary free water loss; peripheral vasoconstriction"},"page":12,"subject":"Physiology","kind":"Clinical vignette","section":"Pre-clinical"},{"n":30,"stem":"A 45-year-old patient of blood group A (subgroup A1) requires an urgent blood transfusion. Cross-matching is performed. A person with blood group O is known as a “universal donor” for red cell transfusions in emergency settings. Which of the following CORRECTLY explains why group O red cells cause less haemolytic risk than other ABO-incompatible transfusions?","options":{"A":"Group O individuals have the H antigen; anti-H antibodies in recipients destroy O red cells slowly","B":"Group O red cells carry both A and B antigens at low density","C":"Group O plasma contains anti-A and anti-B antibodies that are neutralised by recipient red cells","D":"Group O red cells lack A and B surface antigens, so the recipient’s circulating anti-A or anti-B antibodies cannot bind and activate complement on transfused cells"},"page":13,"subject":"Physiology","kind":"Clinical vignette","section":"Pre-clinical"},{"n":31,"stem":"A neurosurgery resident is asked about the composition and flow of cerebrospinal fluid. A 60-year-old patient with normal pressure hydrocephalus has impaired CSF reabsorption. CSF is primarily produced by which structure, and what is the approximate daily production rate?","options":{"A":"Choroid plexus of the lateral, third, and fourth ventricles; approximately 500 mL/day","B":"Ependymal lining of the cerebral cortex; approximately 100 mL/day","C":"Arachnoid granulations; approximately 250 mL/day","D":"Dural venous sinuses; approximately 50 mL/day"},"page":13,"subject":"Physiology","kind":"Clinical vignette","section":"Pre-clinical"},{"n":32,"stem":"A 70-year-old patient with chronic obstructive pulmonary disease (COPD) has a PaO2 of 55 mmHg, PaCO2 of 55 mmHg, and a pH of 7.32. In the context of the haemoglobin-oxygen dissociation curve, a right shift (decreased O2 affinity) occurs due to which combination of factors present in this patient?","options":{"A":"Decreased CO2, alkalosis, and decreased temperature","B":"Increased CO2, acidosis (Bohr effect), and increased 2,3-DPG","C":"Increased CO2 alone; pH and 2,3-DPG are not relevant to the curve","D":"Decreased 2,3-DPG due to chronic hypoxia shifting the curve leftward"},"page":13,"subject":"Physiology","kind":"Clinical vignette","section":"Pre-clinical"},{"n":33,"stem":"A 35-year-old man is admitted with polyuria and polydipsia. Water deprivation test shows urine osmolality of 150 mOsm/kg even after 8 hours of fluid deprivation. After administration of desmopressin (ADH analogue), urine osmolality rises to 650 mOsm/kg. Which diagnosis is MOST consistent?","options":{"A":"Primary (psychogenic) polydipsia","B":"Nephrogenic diabetes insipidus","C":"Central (cranial) diabetes insipidus","D":"Type 2 diabetes mellitus with osmotic diuresis"},"page":14,"subject":"Physiology","kind":"Clinical vignette","section":"Pre-clinical"},{"n":34,"stem":"A 68-year-old patient with sick sinus syndrome undergoes electrophysiology testing. The pacemaker potential (phase 4 depolarisation) of the sinoatrial node differs from that of a ventricular myocyte primarily because SA node phase 4 is driven by which current?","options":{"A":"A large inward Na+ current (fast Na+ channels, INa) identical to that seen in ventricular cells","B":"Outward K+ current (IK) creating spontaneous depolarisation","C":"Inward Ca2+ current through L-type channels alone, without any funny current","D":"The funny current (If, a mixed Na+/K+ inward current) combined with declining IK and a T-type Ca2+ inward current"},"page":14,"subject":"Physiology","kind":"Clinical vignette","section":"Pre-clinical"},{"n":35,"stem":"The diagram below shows a Michaelis-Menten velocity curve for an enzyme under three conditions: no inhibitor, competitive inhibitor, and non-competitive inhibitor. [S] (substrate concentration) v (reaction velocity) None Comp. Non-comp. Vmax V ′ max Vmax Km A kinase inhibitor drug acts as a competitive inhibitor of a target enzyme. Adding excess substrate MOST likely produces which outcome?","options":{"A":"The reaction velocity approaches the same Vmax as the uninhibited enzyme because competitive inhibition is reversible and overcome by high [S]","B":"The reaction velocity is permanently reduced below Vmax regardless of [S]","C":"Vmax is reduced but Km is unchanged","D":"The enzyme is irreversibly inactivated; adding substrate has no effect"},"page":14,"subject":"Biochemistry","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":36,"stem":"A 24-year-old biochemistry student is asked to calculate the net ATP yield from the complete aerobic oxidation of one molecule of glucose. She knows that glycolysis generates 2 ATP (net) and 2 NADH in the cytoplasm, the pyruvate dehydrogenase step generates 2 NADH, and the TCA cycle generates 6 NADH, 2 FADH2, and 2 GTP per glucose. Using the P/O ratios of 2.5 for NADH and 1.5 for FADH2, what is the MOST accurate total ATP yield per glucose?","options":{"A":"36–38 ATP (classic textbook value using P/O of 3 for NADH, 2 for FADH2)","B":"Approximately 30–32 ATP using modern P/O ratios of 2.5 and 1.5","C":"18 ATP (counting only substrate-level phosphorylation)","D":"40 ATP (including energy from membrane potential alone)"},"page":15,"subject":"Biochemistry","kind":"Calculation / interpretation","section":"Pre-clinical"},{"n":37,"stem":"A patient with severe thiamine (vitamin B1) deficiency presents with neurological symptoms and lactic acidosis. Thiamine pyrophosphate (TPP) is a cofactor for multiple enzymes in intermediary metabolism. Which of the following enzymes is NOT dependent on TPP?","options":{"A":"Pyruvate dehydrogenase","B":"α-Ketoglutarate dehydrogenase","C":"Pyruvate carboxylase","D":"Transketolase (pentose phosphate pathway)"},"page":16,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":38,"stem":"A 10-day-old neonate presents with lethargy, vomiting, and hyperammonaemia following protein feeding. Plasma amino acid analysis shows elevated citrulline. Urine orotic acid is increased. Argininosuccinate synthetase deficiency (citrullinaemia type I) is diagnosed. Which of the following BEST explains the elevated orotic acid in urea cycle defects?","options":{"A":"Decreased arginine synthesis reduces feedback inhibition of ornithine transcarbamylase; carbamoyl phosphate diverts into the pyrimidine synthesis pathway producing orotic acid","B":"Excess orotic acid is produced from arginine catabolism in the liver","C":"Orotic acid accumulates because the urea cycle consumes it as an intermediate","D":"Carbamoyl phosphate accumulates in the mitochondria and spills into the cytosol, where it enters the pyrimidine synthesis pathway and is converted to orotic acid"},"page":16,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":39,"stem":"A nutritionist explains to a medical student the key differences between fatty acid synthesis and fatty acid oxidation (β-oxidation). Which of the following statements correctly identifies a difference between these two pathways?","options":{"A":"Fatty acid synthesis occurs in the cytoplasm and uses NADPH; βoxidation occurs in the mitochondrial matrix and generates NADH and FADH2","B":"Both processes occur in the mitochondrial matrix and use the same carrier proteins","C":"Fatty acid synthesis uses FAD and NAD+ as cofactors; β-oxidation uses NADPH","D":"β-Oxidation is the rate-limiting step for cholesterol biosynthesis"},"page":16,"subject":"Biochemistry","kind":"Concept / direct recall","section":"Pre-clinical"},{"n":40,"stem":"The Lineweaver-Burk (double-reciprocal) plots below compare uninhibited enzyme kinetics with two inhibitor conditions. 1/[S] 1/v None Comp. Non-comp. 1/Vmax 1/V ′ max −1/Km−1/K′ m Based on the Lineweaver-Burk plot, non-competitive inhibition is identified when which feature is observed?","options":{"A":"The x-intercept shifts to the right (less negative) but the y-intercept is unchanged","B":"Both the x-intercept and y-intercept shift, indicating changes in both Km and Vmax","C":"The y-intercept increases (higher 1/Vmax) while the x-intercept remains unchanged (same −1/Km), indicating reduced Vmax with unchanged Km","D":"The slope decreases and lines converge at the y-axis"},"page":17,"subject":"Biochemistry","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":41,"stem":"A 55-year-old man with gout is started on allopurinol, which inhibits xanthine oxidase. A rare enzyme deficiency — hypoxanthine-guanine phosphoribosyltransferase (HGPRT) — is responsible for Lesch-Nyhan syndrome. HGPRT is critical for which metabolic pathway?","options":{"A":"De novo purine synthesis from PRPP and glutamine","B":"The purine salvage pathway, converting hypoxanthine and guanine to IMP and GMP using PRPP","C":"De novo pyrimidine synthesis via carbamoyl phosphate","D":"The folate cycle for thymidylate synthesis"},"page":17,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":42,"stem":"A 40-year-old alcoholic man presents with the classic triad of dermatitis, diarrhoea, and dementia (Casal’s necklace rash). Pellagra caused by niacin (vitamin B3) deficiency is diagnosed. Niacin is a precursor of which coenzyme critical for oxidation-reduction reactions in glycolysis and the TCA cycle?","options":{"A":"NAD+ and NADP+","B":"Coenzyme A (CoA)","C":"FAD and FMN","D":"Thiamine pyrophosphate (TPP)"},"page":18,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":43,"stem":"A 30-year-old woman with a strong family history of colorectal cancer is found to carry a germline mutation in the MLH1 gene, which encodes a mismatch repair protein. The mismatch repair (MMR) system corrects errors introduced during DNA replication. Which of the following BEST describes the biochemical basis of MMR?","options":{"A":"MMR removes UV-induced thymine dimers by nucleotide excision","B":"MMR corrects double-strand breaks using homologous recombination with the sister chromatid","C":"MMR recognises and repairs base mismatches and small insertiondeletion loops left after DNA polymerase errors, using strand discrimination signals (e.g., hemi-methylation in bacteria; PCNA-based in humans)","D":"MMR operates only in mitochondrial DNA because nuclear DNA uses base excision repair exclusively"},"page":18,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":44,"stem":"A 55-year-old woman is found to have a BRCA1 mutation. BRCA1 is classified as a tumour suppressor gene and follows the “two-hit” hypothesis. Which of the following is the MOST accurate statement about oncogenes versus tumour suppressor genes?","options":{"A":"Oncogenes require mutation of both alleles (loss of function) to promote tumorigenesis","B":"Oncogenes are gain-of-function mutations; one mutant allele is sufficient (dominant); tumour suppressors are loss-of-function and require both alleles to be inactivated","C":"Tumour suppressor genes promote cell growth; their overexpression causes cancer","D":"Both oncogenes and tumour suppressors are always inherited through the germline"},"page":19,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":45,"stem":"A 55-year-old patient with nephrotic syndrome has a serum albumin of 1.8 g/dL (normal 3.5–5.0 g/dL). He develops bilateral pitting oedema. Besides its oncotic role, albumin performs several important physiological functions. Which of the following is NOT a function of albumin?","options":{"A":"Binding and transport of unconjugated bilirubin","B":"Binding and transport of free fatty acids","C":"Maintenance of plasma colloid osmotic pressure","D":"Synthesis of acute-phase proteins such as C-reactive protein and fibrinogen"},"page":19,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":46,"stem":"The diagram below shows three consecutive steps of glycolysis, with enzymes labelled E1, E2, and E3. Glucose-6-phosphate Fructose-6-phosphate Fructose-1,6-bisphosphate DHAP + G3P E1 E2 (ATP→ADP) E3 –1 ATP Enzyme E2 (which consumes one ATP and is a key regulatory step) is the enzyme that is MOST significantly allosterically inhibited by ATP and citrate, and activated by AMP and fructose-2,6-bisphosphate. What is the identity of E2?","options":{"A":"Phosphofructokinase-1 (PFK-1)","B":"Hexokinase","C":"Phosphoglucose isomerase","D":"Pyruvate kinase"},"page":19,"subject":"Biochemistry","kind":"Visual / interpretation","section":"Pre-clinical"},{"n":47,"stem":"A 19-year-old patient with type 1 diabetes presents in diabetic ketoacidosis (DKA). His arterial blood gas shows pH 7.18, HCO− 3 8 mEq/L, and blood glucose 450 mg/dL. Serum ketones are markedly elevated. The rate-limiting enzyme of ketogenesis in hepatocyte mitochondria is:","options":{"A":"Acetyl-CoA carboxylase","B":"Acyl-CoA dehydrogenase","C":"HMG-CoA synthase (mitochondrial)","D":"HMG-CoA lyase"},"page":20,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":48,"stem":"A 65-year-old housebound woman presents with proximal muscle weakness and bone pain. Her 25-hydroxyvitamin D level is 12 ng/mL (severely deficient). Vitamin D must undergo two hydroxylation steps before becoming biologically active calcitriol. Which of the following CORRECTLY describes the sequential hydroxylations?","options":{"A":"First hydroxylation at position 1 in the kidney; second hydroxylation at position 25 in the liver","B":"First hydroxylation at position 25 in the liver; second hydroxylation at position 1 in the kidney (by 1α-hydroxylase, stimulated by PTH)","C":"Both hydroxylations occur in the kidney under the control of calcitonin","D":"First hydroxylation at position 25 in the skin; second at position 1 in the liver"},"page":20,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":49,"stem":"A 28-year-old patient with Leber’s hereditary optic neuropathy (LHON) carries a point mutation in mitochondrial DNA encoding a subunit of complex I of the electron transport chain. Complex I (NADH dehydrogenase) performs which of the following reactions?","options":{"A":"Transfers electrons from FADH2 to ubiquinone (CoQ) and pumps 4 H+ across the inner mitochondrial membrane","B":"Transfers electrons from ubiquinol to cytochrome c and pumps 4 H+","C":"Reduces O2 to H2O using electrons from cytochrome c and pumps 2 H+","D":"Transfers electrons from NADH to ubiquinone (CoQ) and pumps 4 H+ across the inner mitochondrial membrane per NADH"},"page":21,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":50,"stem":"A 60-year-old woman with rheumatoid arthritis has a markedly elevated erythrocyte sedimentation rate (ESR) and serum C-reactive protein (CRP). CRP is an acute-phase protein synthesised by the liver in response to IL- 6. Which of the following BEST describes the biological function of CRP in innate immunity?","options":{"A":"CRP neutralises bacterial endotoxin by competitive binding to TLR-4 on macrophages","B":"CRP activates the adaptive immune response by presenting antigens to T lymphocytes","C":"CRP binds phosphocholine on the surface of apoptotic cells and microorganisms, activating the classical complement pathway and facilitating opsonisation","D":"CRP inhibits the acute-phase response by suppressing IL-6 secretion from hepatocytes via negative feedback"},"page":21,"subject":"Biochemistry","kind":"Clinical vignette","section":"Pre-clinical"},{"n":51,"stem":"A 62-year-old man is brought to the emergency department 3 hours after the onset of crushing chest pain. His ECG shows ST elevation in leads II, III, and aVF. He is resuscitated but dies 18 hours later. At autopsy, the infarcted myocardium shows preserved cellular outlines with loss of nuclei and cytoplasmic eosinophilia. The diagram below schematically represents the zone of necrosis: Zone X Hyperaemic border Viable Zone X (the necrotic core) in this setting MOST likely represents which type of necrosis?","options":{"A":"Coagulative necrosis","B":"Liquefactive necrosis","C":"Caseous necrosis","D":"Fat necrosis"},"page":21,"subject":"Pathology","kind":"Visual / interpretation","section":"Para-clinical"},{"n":52,"stem":"A pathologist examines a liver biopsy from a 38-year-old woman with chronic hepatitis C infection. On H&E staining, scattered hepatocytes are shrunken, with deeply eosinophilic cytoplasm and pyknotic nuclei, surrounded by a clear halo, without surrounding inflammation. Which of the following BEST distinguishes this process from necrosis?","options":{"A":"Loss of plasma membrane integrity","B":"Release of lysosomal enzymes","C":"Energy (ATP)-dependent process with caspase activation","D":"Neutrophilic infiltration at the site"},"page":22,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":53,"stem":"A 34-year-old man presents with a 3-month history of low-grade fever, weight loss, and a productive cough. Chest X-ray shows an upper-lobe cavitary lesion. Sputum AFB smear is positive. Biopsy of the lung lesion reveals the structure depicted below: Caseous Epithelioid macrophages Langhans GC Lymphocytes The cell type that is the hallmark of this lesion and is derived from circulating monocytes is:","options":{"A":"Langhans giant cell","B":"Epithelioid macrophage","C":"CD8+ cytotoxic T lymphocyte","D":"Plasma cell"},"page":22,"subject":"Pathology","kind":"Visual / interpretation","section":"Para-clinical"},{"n":54,"stem":"A 28-year-old man sustains a deep laceration over his forearm that is left unsutured. Two weeks later, the wound shows granulation tissue with fibroblast proliferation, new capillary formation, and deposition of type III collagen. Which of the following statements about the subsequent remodeling phase is CORRECT?","options":{"A":"Type I collagen is replaced by type III collagen","B":"Tensile strength never exceeds 50% of normal skin","C":"Matrix metalloproteinases (MMPs) are inhibited throughout remodeling","D":"Type III collagen is gradually replaced by type I collagen, increasing tensile strength"},"page":23,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":55,"stem":"A 25-year-old woman develops redness, swelling, and pain in her right hand 24 hours after a thorn puncture. Microscopy of the inflamed tissue shows predominantly neutrophil infiltration. Which of the following mediators is MOST responsible for the increased vascular permeability seen within the first 30 minutes?","options":{"A":"Histamine released from mast cells","B":"Leukotriene B4","C":"Interleukin-1 (IL-1)","D":"Complement C3a only"},"page":23,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":56,"stem":"A 55-year-old woman presents with a breast lump. Biopsy confirms invasive ductal carcinoma. The diagram below represents the TNM staging concept for breast cancer: Tumor size / invasion T1 T2 T3 T4 Nodal spread N0 N1 N2 N3 Metastasis M0 M1 A tumor that has invaded the chest wall (T4), involves 4 axillary lymph nodes (N2), with no distant metastasis (M0) is classified as:","options":{"A":"Stage I","B":"Stage II","C":"Stage IIIB","D":"Stage IV"},"page":24,"subject":"Pathology","kind":"Visual / interpretation","section":"Para-clinical"},{"n":57,"stem":"A 4-year-old child presents with an abdominal mass. Imaging reveals a large renal tumor. Histology shows primitive blastema, epithelial tubules, and stromal cells (triphasic pattern). Molecular analysis reveals loss of both alleles of a tumor suppressor gene on chromosome 11p13. This gene normally functions to:","options":{"A":"Activate the RAS signaling pathway","B":"Phosphorylate and activate CDK4","C":"Encode a growth factor receptor with tyrosine kinase activity","D":"Suppress transcription of genes promoting cell proliferation"},"page":24,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":58,"stem":"A 28-year-old woman with menorrhagia presents with fatigue and pallor. Her CBC shows: Hb 7.8 g/dL, MCV 62 fL, MCH 18 pg, RDW 18% (high). Peripheral smear shows hypochromic microcytic RBCs with pencil cells. Serum ferritin is 4 ng/mL. Which of the following laboratory findings is ALSO expected?","options":{"A":"Increased total iron-binding capacity (TIBC)","B":"Decreased TIBC","C":"Normal serum iron with increased ferritin","D":"Increased serum iron with decreased TIBC"},"page":25,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":59,"stem":"A 16-year-old boy presents with mild jaundice, splenomegaly, and a history of similar episodes since childhood. His elder brother has the same condition. CBC shows: Hb 9.5 g/dL, MCV 78 fL, MCHC 38 g/dL (elevated), reticulocyte count 8%. Osmotic fragility test is positive. The PRIMARY molecular defect in this condition is:","options":{"A":"Deficiency of glucose-6-phosphate dehydrogenase","B":"Defect in spectrin or ankyrin protein of the RBC cytoskeleton","C":"Abnormal hemoglobin chain (HbS)","D":"Acquired complement-mediated RBC destruction"},"page":25,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":60,"stem":"A 52-year-old man presents with fatigue, left upper quadrant pain, and weight loss. Examination reveals massive splenomegaly. CBC: WBC 120,000/µL with a left shift showing myelocytes, metamyelocytes, and basophilia; Hb 9 g/dL; platelets 800,000/µL. Leukocyte alkaline phosphatase (LAP) score is very low. Cytogenetics reveals t(9;22)(q34;q11). This translocation creates:","options":{"A":"A mutant RAS protein with constitutive GTPase activity","B":"An abnormal transcription factor BCL-2/IgH fusion","C":"BCR-ABL fusion protein with constitutive tyrosine kinase activity","D":"Loss of WT1 tumor suppressor gene"},"page":25,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":61,"stem":"A 22-year-old man presents with painless cervical lymphadenopathy, lowgrade fever, night sweats, and 8 kg weight loss over 3 months. CT shows mediastinal involvement. Lymph node biopsy shows large binucleated cells with prominent ”owl-eye” nucleoli in a background of lymphocytes, plasma cells, and eosinophils. These large cells are:","options":{"A":"Reed-Sternberg cells of Hodgkin lymphoma","B":"Burkitt lymphoma cells with starry-sky pattern","C":"Follicular center B-cells with BCL-2 overexpression","D":"Reed-Sternberg variant cells of non-Hodgkin lymphoma"},"page":26,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":62,"stem":"A 58-year-old man with a 30-year history of smoking and hypertension undergoes coronary angiography showing 80% stenosis of the left anterior descending artery. The cross-section of an atherosclerotic plaque is shown schematically below: Lumen Lipid core Fibrous cap Foam cells Media/Adventitia Foam cells in the atheromatous plaque are derived PRIMARILY from:","options":{"A":"Smooth muscle cells only","B":"Endothelial cells that undergo mesenchymal transition","C":"Platelets that aggregate at the lesion site","D":"Macrophages that ingest oxidized LDL"},"page":26,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":63,"stem":"A 65-year-old man is admitted with an anterior STEMI and is successfully thrombolysed. On day 5, he develops sudden severe hypotension and a new harsh pansystolic murmur at the left sternal border with a thrill. Echocardiography reveals a left-to-right shunt. The MOST likely complication responsible is:","options":{"A":"Free wall rupture with tamponade","B":"Rupture of the interventricular septum","C":"Acute mitral regurgitation due to papillary muscle rupture","D":"Left ventricular aneurysm"},"page":26,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":64,"stem":"A 7-year-old boy develops periorbital puffiness and frothy urine 2 weeks after a sore throat. Urinalysis: protein 3+ (4 g/24 h), hematuria, RBC casts, and C3 complement is low. Renal biopsy by electron microscopy shows subepithelial ”humps.” This pattern is MOST consistent with:","options":{"A":"Minimal change disease","B":"IgA nephropathy (Berger’s disease)","C":"Post-streptococcal (diffuse proliferative) glomerulonephritis","D":"Membranous nephropathy"},"page":27,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":65,"stem":"A 4-year-old girl presents with generalized edema, heavy proteinuria (10 g/day), hypoalbuminemia (serum albumin 1.8 g/dL), and hyperlipidemia. Urine microscopy shows oval fat bodies. Renal biopsy by light microscopy is essentially normal; electron microscopy shows diffuse effacement of podocyte foot processes. The drug of choice for initial treatment is:","options":{"A":"Prednisolone (corticosteroids)","B":"Cyclophosphamide","C":"Captopril (ACE inhibitor)","D":"Furosemide alone"},"page":27,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":66,"stem":"A 48-year-old man with a 20-year history of heavy alcohol use presents with jaundice, tender hepatomegaly, and fever. Labs: AST 280 U/L, ALT 110 U/L (AST:ALT ratio >2:1), GGT markedly elevated, bilirubin 5.2 mg/dL. Liver biopsy shows hepatocyte ballooning, Mallory-Denk bodies, neutrophil infiltration, and pericellular fibrosis. The intracellular inclusions (Mallory-Denk bodies) are composed of:","options":{"A":"Accumulated glycogen granules","B":"Fat vacuoles from triglyceride accumulation","C":"Periodic acid-Schiff (PAS)-positive granules of α-1-antitrypsin","D":"Aggregated intermediate filaments (cytokeratin 8/18)"},"page":27,"subject":"Pathology","kind":"Calculation / interpretation","section":"Para-clinical"},{"n":67,"stem":"A 32-year-old man is found to have HBsAg positive, HBeAg positive, anti-HBc IgM positive, and high HBV DNA. He is asymptomatic but has elevated ALT. Which of the following indicates HIGH infectivity?","options":{"A":"Anti-HBs positivity","B":"HBeAg positivity","C":"Anti-HBe positivity","D":"Anti-HBc IgG alone (with negative HBsAg)"},"page":28,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":68,"stem":"A 55-year-old man with hepatitis C-related cirrhosis presents with suddenonset hematemesis. Endoscopy reveals bleeding esophageal varices. The pathophysiological basis of variceal formation in cirrhosis is:","options":{"A":"Decreased hepatic arterial pressure","B":"Hypoalbuminemia causing reduced oncotic pressure","C":"Portal hypertension due to increased intrahepatic vascular resistance","D":"Hypercoagulable state causing portal vein thrombosis only"},"page":28,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":69,"stem":"A 70-year-old man with diabetes is admitted with a 4-day history of productive cough, fever, and right-sided chest pain. CXR shows consolidation of the right lower lobe. His sputum Gram stain shows Gram-positive diplococci. The MOST common organism causing community-acquired lobar pneumonia in adults is:","options":{"A":"Streptococcus pneumoniae","B":"Klebsiella pneumoniae","C":"Staphylococcus aureus","D":"Haemophilus influenzae"},"page":28,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":70,"stem":"A 42-year-old HIV-positive man (CD4 count 80 cells/µL) presents with fever, night sweats, and diffuse bilateral pulmonary infiltrates. AFB smear of BAL is positive. Which feature of TB pathology is LEAST likely to be seen in this severely immunocompromised patient?","options":{"A":"Numerous AFB organisms","B":"Widespread caseation","C":"Miliary pattern of dissemination","D":"Well-formed epithelioid granulomas with Langhans giant cells"},"page":29,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":71,"stem":"A 62-year-old heavy smoker presents with a 3-cm hilar mass, hemoptysis, and hypercalcemia. No PTH-related protein elevation is confirmed by lab. Bronchoscopy biopsy shows large polygonal cells with intercellular bridges and keratin pearls. The MOST likely diagnosis is:","options":{"A":"Small cell (oat cell) carcinoma","B":"Squamous cell carcinoma of the lung","C":"Adenocarcinoma of the lung","D":"Large cell carcinoma"},"page":29,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":72,"stem":"A 55-year-old man with a PSA of 28 ng/mL undergoes prostate biopsy showing adenocarcinoma. The PSA is used as a tumor marker. Regarding tumor markers, which of the following statements is CORRECT?","options":{"A":"AFP is the most specific marker for prostate carcinoma","B":"CEA is specific for colorectal carcinoma and is used for screening","C":"Tumor markers are useful for monitoring treatment response and detecting recurrence","D":"CA-125 is highly specific for ovarian cancer and is used for populationbased screening"},"page":29,"subject":"Pathology","kind":"Clinical vignette","section":"Para-clinical"},{"n":73,"stem":"A 35-year-old man with anaphylactic shock is brought to the emergency department with blood pressure 60/30 mmHg, heart rate 130 bpm, and severe bronchospasm. The drug of choice for anaphylactic shock that acts on α1, β1, and β2 receptors is:","options":{"A":"Epinephrine (adrenaline) 0.5 mg IM","B":"Norepinephrine IV infusion","C":"Phenylephrine IV","D":"Dopamine 5 µg/kg/min IV"},"page":29,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":74,"stem":"A 28-year-old farmer is brought unconscious with excessive secretions, miosis, bradycardia (HR 42 bpm), bronchospasm, and muscle fasciculations. His family reports he was spraying pesticides. Initial management includes atropine and pralidoxime. Pralidoxime is MOST effective when given:","options":{"A":"After 72 hours, when the clinical picture is clear","B":"Only after all atropine requirements are met","C":"As a sole agent without atropine","D":"Within 24–48 hours before ”aging” of acetylcholinesterase occurs"},"page":30,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":75,"stem":"A 25-year-old woman with a history of generalized tonic-clonic seizures is started on valproic acid. She becomes pregnant. The MOST significant teratogenic risk associated with valproate use in the first trimester is:","options":{"A":"Neonatal hypoglycemia","B":"Neural tube defects (spina bifida)","C":"Cleft palate alone","D":"Neonatal hemorrhage due to vitamin K deficiency"},"page":30,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":76,"stem":"A 38-year-old man with schizophrenia has been on haloperidol for 6 months. He now presents with slow, writhing involuntary movements of his tongue and face that persist even after the drug is reduced. This adverse effect is known as:","options":{"A":"Akathisia","B":"Acute dystonia","C":"Tardive dyskinesia","D":"Neuroleptic malignant syndrome"},"page":30,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":77,"stem":"A 42-year-old woman with major depressive disorder is started on fluoxetine. She is also taking tramadol for chronic pain. Three weeks later she develops agitation, hyperthermia, myoclonus, and diaphoresis. This life-threatening interaction is caused by:","options":{"A":"Serotonin syndrome due to excess serotonergic activity","B":"Neuroleptic malignant syndrome from dopamine blockade","C":"Anticholinergic toxidrome from muscarinic blockade","D":"Sympathomimetic crisis from norepinephrine excess"},"page":31,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":78,"stem":"A 55-year-old man with cancer pain is on long-term morphine. He presents with severe respiratory depression (RR 6/min), miosis, and unconsciousness after accidentally receiving an extra dose. The drug of choice for reversal is:","options":{"A":"Nalbuphine","B":"Buprenorphine","C":"Pentazocine","D":"Naloxone IV"},"page":31,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":79,"stem":"A 45-year-old man requires general anaesthesia for an elective cholecystectomy. Induction is achieved with propofol. Which of the following BEST describes propofol’s mechanism of action?","options":{"A":"Blockade of NMDA glutamate receptors","B":"Potentiation of GABAA receptor-mediated chloride influx","C":"Inhibition of voltage-gated sodium channels","D":"Agonism at µ-opioid receptors"},"page":31,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":80,"stem":"A pharmacologist plots full dose-response curves for two drugs acting on the same receptor. The graph below shows Drug A and Drug B: Log [Dose] Effect (%) Drug A Drug B 50% AED50 BED50 From the graph, Drug A compared to Drug B has:","options":{"A":"Greater efficacy and greater potency","B":"Same efficacy but lesser potency","C":"Greater potency but the same maximum efficacy","D":"Lesser potency and lesser efficacy"},"page":31,"subject":"Pharmacology","kind":"Visual / interpretation","section":"Para-clinical"},{"n":81,"stem":"A 52-year-old man with hypertension and benign prostatic hyperplasia (BPH) is started on a single drug that will treat both conditions simultaneously. The mechanism of this drug is:","options":{"A":"Blockade of β1 adrenergic receptors reducing cardiac output","B":"Inhibition of ACE preventing angiotensin II formation","C":"Blockade of calcium channels in vascular smooth muscle","D":"Blockade of α1 adrenergic receptors causing vasodilation and relaxing bladder neck"},"page":32,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":82,"stem":"A 68-year-old man with a previous MI develops ventricular tachycardia (VT). He is hemodynamically stable. The drug of choice for hemodynamically stable VT that acts by blocking fast sodium channels (Class IA/IB) is:","options":{"A":"Amiodarone IV","B":"Verapamil IV","C":"Digoxin","D":"Adenosine IV"},"page":32,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":83,"stem":"A 60-year-old man with heart failure with reduced ejection fraction (HFrEF, EF 30%) is on furosemide, enalapril, and carvedilol. He develops worsening edema despite optimal doses. Which of the following ADDITIONAL drug has been shown to reduce mortality in this setting?","options":{"A":"Digoxin","B":"Spironolactone (aldosterone antagonist)","C":"Hydralazine alone","D":"Amlodipine"},"page":33,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":84,"stem":"A 70-year-old woman with non-valvular atrial fibrillation requires anticoagulation for stroke prevention. She has normal renal function. She is started on rivaroxaban. The mechanism of rivaroxaban is:","options":{"A":"Inhibition of thrombin (Factor IIa) directly","B":"Inhibition of vitamin K-dependent clotting factor synthesis","C":"Direct inhibition of Factor Xa","D":"Activation of antithrombin III to inhibit multiple clotting factors"},"page":33,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":85,"stem":"A 5-year-old boy is prescribed amoxicillin for acute otitis media. His mother reports he had a rash (urticaria) with amoxicillin 1 year ago. Which of the following is the MOST appropriate alternative?","options":{"A":"Ampicillin (another aminopenicillin)","B":"Cephalexin (first-generation cephalosporin)","C":"Piperacillin-tazobactam","D":"Azithromycin (macrolide)"},"page":33,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":86,"stem":"A 65-year-old man with hospital-acquired pneumonia is started on gentamicin. After 7 days, he develops rising serum creatinine and reports difficulty hearing. Which of the following monitoring parameters is MOST important for aminoglycoside therapy?","options":{"A":"Trough serum levels to assess nephrotoxicity risk and audiometry","B":"Liver function tests for hepatotoxicity","C":"Platelet count for thrombocytopenia","D":"INR for anticoagulant interaction"},"page":33,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":87,"stem":"A 55-year-old woman with a urinary tract infection is treated with ciprofloxacin. She concurrently takes antacids containing magnesium. The pharmacokinetic concern is:","options":{"A":"Ciprofloxacin increases the renal excretion of magnesium","B":"Magnesium induces CYP450 enzymes, increasing ciprofloxacin metabolism","C":"Divalent cations chelate ciprofloxacin in the gut, markedly reducing absorption","D":"Ciprofloxacin is contraindicated only because of cardiac QTc prolongation with Mg"},"page":34,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":88,"stem":"A 35-year-old HIV-positive patient (CD4 count 50 cells/µL) develops headache, fever, and neck stiffness. CSF India ink preparation reveals encapsulated yeast. He is started on amphotericin B deoxycholate. The mechanism of amphotericin B is:","options":{"A":"Inhibition of beta-glucan synthase (cell wall synthesis)","B":"Binding to ergosterol in fungal cell membrane causing pore formation","C":"Inhibition of lanosterol 14α-demethylase (CYP51)","D":"Inhibition of fungal DNA synthesis"},"page":34,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":89,"stem":"A 32-year-old man newly diagnosed with HIV (CD4 230 cells/µL, viral load 120,000 copies/mL) is started on tenofovir + emtricitabine + dolutegravir. Dolutegravir belongs to which drug class and acts by:","options":{"A":"Nucleoside reverse transcriptase inhibitor (NRTI) — inhibits viral RNA-dependent DNA polymerase","B":"Protease inhibitor — prevents cleavage of viral polyprotein","C":"Non-nucleoside reverse transcriptase inhibitor (NNRTI) — binds allosteric site of reverse transcriptase","D":"Integrase strand transfer inhibitor (INSTI) — prevents integration of viral DNA into host genome"},"page":34,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":90,"stem":"A 28-year-old man is started on HRZE (isoniazid, rifampicin, ethambutol, pyrazinamide) for pulmonary TB. After 2 months, he develops peripheral neuropathy. The drug responsible and the mechanism are:","options":{"A":"Rifampicin — inhibits mycobacterial RNA polymerase causing neuronal toxicity","B":"Ethambutol — inhibits arabinosyl transferase causing optic neuritis, not peripheral neuropathy","C":"Isoniazid — inhibits pyridoxine (vitamin B6) metabolism causing peripheral neuropathy","D":"Pyrazinamide — inhibits fatty acid synthesis causing peripheral neuropathy"},"page":35,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":91,"stem":"A 48-year-old woman with rheumatoid arthritis on long-term diclofenac develops epigastric pain and melena. Endoscopy shows a gastric ulcer. The MOST important mechanism by which NSAIDs cause GI injury is:","options":{"A":"Inhibition of COX-1 reducing prostaglandin E2 synthesis, impairing mucosal protection","B":"Direct topical acid injury to gastric mucosa when taken on an empty stomach","C":"Selective COX-2 inhibition increasing thromboxane A2","D":"Inhibition of histamine H2 receptors in gastric parietal cells"},"page":35,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":92,"stem":"A 35-year-old woman with breast cancer (ER+/PR+, HER2-) receives tamoxifen as adjuvant therapy. The mechanism of action of tamoxifen is:","options":{"A":"Aromatase inhibition preventing peripheral conversion of androgens to estrogens","B":"Competitive antagonism at estrogen receptors in breast tissue (SERM)","C":"Direct cytotoxic alkylation of tumor cell DNA","D":"Inhibition of topoisomerase II causing double-strand DNA breaks"},"page":35,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":93,"stem":"A 72-year-old man with insomnia is prescribed a benzodiazepine. Due to his age and risk of accumulation, the MOST appropriate short-acting benzodiazepine with no active metabolites is:","options":{"A":"Diazepam","B":"Chlordiazepoxide","C":"Flurazepam","D":"Lorazepam"},"page":36,"subject":"Pharmacology","kind":"Clinical vignette","section":"Para-clinical"},{"n":94,"stem":"A pharmacologist studies the effect of a reversible competitive inhibitor on an enzyme. The Lineweaver-Burk (double-reciprocal) plot is shown: 1/[S] 1/V No inhibitor +Inhibitor −1/Km 1/Vmax (Both lines cross y-axis at same point) Which of the following changes is characteristic of competitive inhibition as shown?","options":{"A":"Decreased Vmax, unchanged Km","B":"Decreased Vmax, increased Km","C":"Unchanged Vmax, increased apparent Km","D":"Unchanged Vmax, decreased Km"},"page":36,"subject":"Pharmacology","kind":"Visual / interpretation","section":"Para-clinical"},{"n":95,"stem":"A 12-year-old boy presents with a painful, fluctuant swelling over his right forearm following a minor abrasion one week ago. Pus culture shows Gram-positive cocci in clusters, coagulase-positive, beta-hemolytic on blood agar. The organism produces a toxin that destroys leukocytes. This toxin is:","options":{"A":"Panton-Valentine leukocidin (PVL)","B":"Toxic shock syndrome toxin-1 (TSST-1)","C":"Exfoliatin (Epidermolytic toxin)","D":"Streptolysin O"},"page":36,"subject":"Microbiology","kind":"Clinical vignette","section":"Para-clinical"},{"n":96,"stem":"A 3-day-old neonate has not passed meconium and has difficulty feeding. He was born at home; the umbilical cord was cut with unsterilized scissors. He develops muscle rigidity and spasms triggered by light stimulation. The MOST likely causative organism is:","options":{"A":"Clostridium perfringens","B":"Clostridium difficile","C":"Bacillus anthracis","D":"Clostridium tetani"},"page":37,"subject":"Microbiology","kind":"Concept / direct recall","section":"Para-clinical"},{"n":97,"stem":"A 5-year-old child from a flood-affected area presents with sudden-onset profuse watery ”rice water” diarrhea without blood or mucus, and severe dehydration. Stool culture on TCBS agar shows yellow colonies. The organism produces a toxin that acts by:","options":{"A":"Inhibiting protein synthesis at the 60S ribosomal subunit","B":"Permanently activating adenylate cyclase via ADP-ribosylation of Gs, increasing cAMP and causing secretory diarrhea","C":"Disrupting tight junctions causing paracellular leakage","D":"Producing a cytotoxin causing bloody diarrhea"},"page":37,"subject":"Microbiology","kind":"Clinical vignette","section":"Para-clinical"},{"n":98,"stem":"A 25-year-old man returns from a trip to Southeast Asia with a 10-day history of stepwise rising fever, relative bradycardia, coated tongue, rose spots on abdomen, and splenomegaly. Blood culture at 1st week is MOST likely to grow:","options":{"A":"Shigella dysenteriae","B":"Vibrio cholerae","C":"Salmonella typhi","D":"Escherichia coli O157:H7"},"page":37,"subject":"Microbiology","kind":"Clinical vignette","section":"Para-clinical"},{"n":99,"stem":"A 30-year-old man tests positive for HIV. The schematic below represents key steps in the HIV replication cycle: 1. Attachment (gp120/CD4) 2. Fusion (gp41) 3. Reverse Transcription (RT) 4. Integration (Integrase) 5. Transcription & Translation 6. Protease cleavage & Budding Target of NR- TIs/NNRTIs Target of integrase inhibitors Target of protease inhibitors The FIRST identifiable serological marker to become positive after HIV infection (within 2 weeks, during the ”window period” of antibody testing) is:","options":{"A":"HIV p24 antigen","B":"Anti-HIV IgG antibodies","C":"Anti-HIV IgM antibodies","D":"HIV RNA viral load (by 4th generation ELISA)"},"page":38,"subject":"Microbiology","kind":"Visual / interpretation","section":"Para-clinical"},{"n":100,"stem":"A 35-year-old woman is found to be HBsAg positive on routine screening. Further testing: HBeAg negative, anti-HBe positive, HBV DNA 180 IU/mL (low). She has no symptoms and normal liver function. Her serology indicates:","options":{"A":"Active hepatitis B with high infectivity","B":"Acute hepatitis B infection","C":"Occult hepatitis B infection","D":"Inactive HBsAg carrier state (low replication phase)"},"page":38,"subject":"Microbiology","kind":"Clinical vignette","section":"Para-clinical"},{"n":101,"stem":"A 28-year-old man with HIV (CD4 count 40 cells/µL) presents with 3 weeks of progressive headache and mild neck stiffness. CSF shows: opening pressure 320 mmH2O, lymphocytic pleocytosis, low glucose, elevated protein. India ink stain shows encapsulated budding yeast. The BEST confirmatory test for this infection is:","options":{"A":"Sabouraud dextrose agar culture at 37◦C","B":"CSF cryptococcal antigen (CrAg) detection","C":"Galactomannan antigen assay","D":"Potassium hydroxide (KOH) preparation of sputum"},"page":39,"subject":"Microbiology","kind":"Clinical vignette","section":"Para-clinical"},{"n":102,"stem":"A 7-year-old boy presents with sore throat, fever, and cervical lymphadenopathy. On examination his tonsils are erythematous with exudates and his tongue is red and bumpy (”strawberry tongue”). He also has a diffuse erythematous rash sparing the face. The organism responsible elaborates which toxin causing the rash?","options":{"A":"Leukocidin","B":"Streptolysin S","C":"Erythrogenic (pyrogenic) exotoxin (Streptococcal pyogenic exotoxin)","D":"Streptokinase"},"page":39,"subject":"Microbiology","kind":"Clinical vignette","section":"Para-clinical"},{"n":103,"stem":"A 22-year-old man returns from sub-Saharan Africa with fever occurring every 48 hours, rigors, and severe headache. Peripheral blood smear shows ring forms within RBCs and banana-shaped gametocytes. Which species of Plasmodium is responsible and what is the serious complication it can cause?","options":{"A":"P. falciparum — cerebral malaria due to cytoadherence of parasitized RBCs","B":"P. vivax — relapse due to hypnozoites in liver","C":"P. malariae — quartan nephrotic syndrome","D":"P. ovale — mild disease with relapses"},"page":39,"subject":"Microbiology","kind":"Clinical vignette","section":"Para-clinical"},{"n":104,"stem":"A 30-year-old man from a rural area presents with 2 weeks of bloody mucoid diarrhea and right upper quadrant pain. Stool microscopy shows trophozoites with ingested RBCs. Ultrasonography reveals a single 8 cm hepatic lesion with ”anchovy sauce” fluid. The drug of choice is:","options":{"A":"Chloroquine alone","B":"Paromomycin (luminal agent) alone","C":"Albendazole","D":"Metronidazole followed by a luminal agent (paromomycin or diloxanide furoate)"},"page":40,"subject":"Microbiology","kind":"Clinical vignette","section":"Para-clinical"},{"n":105,"stem":"The diagram below categorizes the four Gell and Coombs hypersensitivity types: Type I (Immediate) IgE + Mast cells Anaphylaxis asthma Type II (Cytotoxic) IgG IgM + complement Hemolytic anemia Type III (Immune complex) IgG complexes + complement SLE serum sickness Type IV (Delayed) T lymphocytes (no Ab) TB contact dermatitis Type Mediator Example A 45-year-old nurse develops an intensely pruritic, vesicular rash on her hands 48 hours after wearing latex gloves. The hypersensitivity type responsible is:","options":{"A":"Type I (IgE-mediated)","B":"Type II (cytotoxic)","C":"Type IV (delayed-type / cell-mediated)","D":"Type III (immune complex-mediated)"},"page":40,"subject":"Microbiology","kind":"Visual / interpretation","section":"Para-clinical"},{"n":106,"stem":"A 19-year-old student presents with sudden high fever (40◦C), severe retro-orbital pain, myalgia, and a petechial rash on the trunk. CBC: WBC 2,800/µL, platelets 48,000/µL. NS1 antigen test is positive on day 3. What is the MOST important pathophysiological mechanism of thrombocytopenia in dengue?","options":{"A":"Disseminated intravascular coagulation (DIC) consuming platelets","B":"Bone marrow suppression and platelet destruction by virus/immune mechanisms","C":"Hypersplenism from dengue hepatitis","D":"Autoimmune antibody (anti-platelet IgG) formation only"},"page":40,"subject":"Microbiology","kind":"Clinical vignette","section":"Para-clinical"},{"n":107,"stem":"The schematic below shows the cell wall architecture of Gram-positive and Gram-negative bacteria: Gram-positive Thick peptidoglycan Cytoplasmic membrane Gram-negative Cytoplasmic membrane Thin peptidoglycan Periplasmic space Outer membrane (LPS) Which of the following is a unique component of the Gram-negative outer membrane NOT found in Gram-positive bacteria?","options":{"A":"Teichoic acid","B":"Peptidoglycan","C":"Lipopolysaccharide (LPS / endotoxin)","D":"N-acetylmuramic acid"},"page":41,"subject":"Microbiology","kind":"Visual / interpretation","section":"Para-clinical"},{"n":108,"stem":"A 14-year-old boy from a rural farming community presents with iron deficiency anemia and hypoalbuminemia. He is found to have eosinophilia (22%) and a positive stool examination showing oval eggs with thin shells. The mechanism of anemia in hookworm infection is:","options":{"A":"Intravascular hemolysis of infected RBCs","B":"B12 deficiency due to ileal colonization and binding","C":"Bone marrow suppression by helminthic toxins","D":"Chronic intestinal blood loss from worm feeding on intestinal villi plus blood sucking"},"page":41,"subject":"Microbiology","kind":"Clinical vignette","section":"Para-clinical"},{"n":109,"stem":"A body is discovered in a room. On examination at 2 PM, the body is found to have well-established rigor mortis in all muscle groups (jaw, neck, trunk, limbs) and greenish discoloration of the right iliac fossa. Body temperature is 28◦C (room temperature 22◦C). Approximately when did death MOST likely occur?","options":{"A":"12–24 hours before discovery","B":"2–4 hours before discovery","C":"36–48 hours before discovery","D":"Over 5 days before discovery"},"page":42,"subject":"Forensic Medicine","kind":"Concept / direct recall","section":"Para-clinical"},{"n":110,"stem":"A 28-year-old woman is found hanging in her apartment. At autopsy, the ligature mark is oblique, incomplete (interrupted), and situated above the thyroid cartilage. There is no fracture of cervical vertebrae. Petechiae (Tardieu spots) are seen in the conjunctivae. The cause of death is:","options":{"A":"Judicial (homicidal) hanging — fracture-dislocation of C2","B":"Suicidal hanging — asphyxia due to venous obstruction and airway compression","C":"Manual strangulation — bilateral carotid pressure","D":"Garroting — ligature mark is horizontal and complete"},"page":42,"subject":"Forensic Medicine","kind":"Clinical vignette","section":"Para-clinical"},{"n":111,"stem":"A 35-year-old farmer is rushed to the ER after ingesting a pesticide. He has profuse salivation, lacrimation, urination, diarrhea, bradycardia (HR 40 bpm), and severe bronchospasm. His pupils are pin-point. The antidote that addresses the central and peripheral muscarinic features is:","options":{"A":"Pralidoxime (PAM) alone","B":"Diazepam for seizure control only","C":"Atropine (large repeated doses titrated to drying of secretions)","D":"N-acetylcysteine"},"page":42,"subject":"Forensic Medicine","kind":"Clinical vignette","section":"Para-clinical"},{"n":112,"stem":"A 40-year-old man sustains burns in a house fire. At autopsy, the epidermis and part of dermis are destroyed with blistering; the skin beneath the blister is red and moist. Vital reaction (inflammatory response) is present. Which degree of burn does this represent?","options":{"A":"Second degree (partial thickness) burn — antemortem","B":"First degree (superficial/erythema) burn — antemortem","C":"Third degree (full thickness) burn — antemortem","D":"Charring — postmortem artefact"},"page":43,"subject":"Forensic Medicine","kind":"Clinical vignette","section":"Para-clinical"},{"n":113,"stem":"A family of four is found unresponsive in a closed room with a kerosene heater in winter. Postmortem examination shows cherry-red discoloration of skin, blood, and viscera. COHb level is 60%. CO toxicity kills by:","options":{"A":"Forming metHb which cannot carry oxygen","B":"Direct cardiac toxicity by binding to cardiac myosin","C":"Inhibiting cytochrome c oxidase and forming carboxymyoglobin causing left-shift of HbO2 curve only","D":"Binding to Hb with 240× greater affinity than O2 AND inhibiting mitochondrial cytochrome oxidase, causing cellular hypoxia"},"page":43,"subject":"Forensic Medicine","kind":"Concept / direct recall","section":"Para-clinical"},{"n":114,"stem":"A 25-year-old man is brought to the ER with a stab wound to the left chest. He is unconscious. No relatives are present. The treating physician needs to perform an emergency surgery. The CORRECT medicolegal principle governing this situation in India is:","options":{"A":"Surgery cannot be performed without written consent from the next of kin","B":"Emergency surgery can proceed under the doctrine of implied consent to save life","C":"The doctor must wait for police clearance before any intervention","D":"Written consent from a magistrate is mandatory before any emergency procedure"},"page":43,"subject":"Forensic Medicine","kind":"Clinical vignette","section":"Para-clinical"},{"n":115,"stem":"A new screening test for tuberculosis is evaluated in a study. The results are presented in the 2×2 table below: Disease+ Disease- Test+ Test- TP = 90 FP = 20 FN = 10 TN = 180 All disease+: 100 All disease-: 200 The sensitivity and specificity of this test are, respectively:","options":{"A":"Sensitivity 81.8%, Specificity 94.7%","B":"Sensitivity 94.7%, Specificity 81.8%","C":"Sensitivity 90%, Specificity 90%","D":"Sensitivity 80%, Specificity 75%"},"page":44,"subject":"Community Medicine","kind":"Calculation / interpretation","section":"Para-clinical"},{"n":116,"stem":"In a cohort study of 10,000 smokers and 10,000 non-smokers followed for 20 years, 400 smokers and 80 non-smokers developed lung cancer. The relative risk (RR) of lung cancer in smokers compared to nonsmokers is:","options":{"A":"2.0","B":"5.0","C":"8.0","D":"10.0"},"page":44,"subject":"Community Medicine","kind":"Calculation / interpretation","section":"Para-clinical"},{"n":117,"stem":"A 6-week-old infant is brought for immunization as per the National Immunization Schedule (NIS) of India. According to the current NIS, which of the following vaccines is NOT given at 6 weeks of age?","options":{"A":"OPV (Oral Polio Vaccine)","B":"Pentavalent vaccine (DPT + Hep B + Hib)","C":"Rotavirus vaccine","D":"MMR (Measles-Mumps-Rubella)"},"page":44,"subject":"Community Medicine","kind":"Concept / direct recall","section":"Para-clinical"},{"n":118,"stem":"Following heavy monsoon flooding, an outbreak of jaundice with nausea, abdominal pain, and dark urine occurs in a village. The disease has an incubation period of 15–45 days, is self-limiting, and does NOT lead to chronic infection. The MOST likely causative agent is:","options":{"A":"Hepatitis B virus","B":"Hepatitis A virus","C":"Hepatitis C virus","D":"Hepatitis E virus"},"page":45,"subject":"Community Medicine","kind":"Concept / direct recall","section":"Para-clinical"},{"n":119,"stem":"In a malaria-endemic district, the district health officer implements ”source reduction” as the primary vector control strategy. This refers to:","options":{"A":"Indoor residual spraying (IRS) with DDT or pyrethroids","B":"Use of long-lasting insecticidal nets (LLINs)","C":"Elimination of mosquito breeding sites (stagnant water, draining swamps)","D":"Biological control using Bacillus thuringiensis israelensis (Bti)"},"page":45,"subject":"Community Medicine","kind":"Concept / direct recall","section":"Para-clinical"},{"n":120,"stem":"The MOST sensitive indicator of the health status of a community and the quality of obstetric and pediatric care is:","options":{"A":"Infant mortality rate (IMR)","B":"Crude birth rate (CBR)","C":"Total fertility rate (TFR)","D":"Maternal mortality ratio (MMR)"},"page":45,"subject":"Community Medicine","kind":"Calculation / interpretation","section":"Para-clinical"},{"n":121,"stem":"During an outbreak of typhoid fever in a residential school, 120 students were exposed to a common water source. Of these, 30 developed typhoid fever. A subsequent investigation revealed that among the 30 primary cases, 10 had family contacts (total 50 family contacts), and 5 of those family contacts developed typhoid fever. The secondary attack rate among family contacts is:","options":{"A":"10%","B":"25%","C":"4.2%","D":"16.7%"},"page":45,"subject":"Community Medicine","kind":"Concept / direct recall","section":"Clinical Medicine"},{"n":122,"stem":"A new rapid diagnostic test for pulmonary tuberculosis is evaluated against sputum culture (gold standard) in 400 patients. The results are shown in the contingency table below: Test Culture + Culture – Test + 140 (TP) 20 (FP) Test – 10 (FN) 230 (TN) The specificity of this test is:","options":{"A":"93.3%","B":"92.0%","C":"87.5%","D":"96.0%"},"page":46,"subject":"Community Medicine","kind":"Calculation / interpretation","section":"Clinical Medicine"},{"n":123,"stem":"In a cross-sectional survey of a district with a population of 50,000, a total of 2,500 individuals were found to have hypertension at a single point in time. During the previous year, 500 new cases of hypertension were diagnosed in the same population. Which of the following correctly states the point prevalence of hypertension?","options":{"A":"1% (500/50,000)","B":"0.5% (250/50,000)","C":"5% (2,500/50,000)","D":"2% (1,000/50,000)"},"page":46,"subject":"Community Medicine","kind":"Concept / direct recall","section":"Clinical Medicine"},{"n":124,"stem":"In a cohort study examining the association between cigarette smoking and lung cancer, the following data were obtained over 10 years: Group Cancer (+) No Cancer (–) Smokers (1000) Non-smokers (1000) 20 The relative risk (RR) of developing lung cancer in smokers compared to non-smokers is:","options":{"A":"2.5","B":"3.0","C":"4.0","D":"5.0"},"page":47,"subject":"Community Medicine","kind":"Calculation / interpretation","section":"Clinical Medicine"},{"n":125,"stem":"A randomised controlled trial on use of aspirin in secondary prevention of myocardial infarction shows that the event rate in the treatment group was 8% and the event rate in the placebo group was 12% over 5 years. The number needed to treat (NNT) to prevent one additional myocardial infarction is:","options":{"A":"","B":"","C":"","D":""},"page":47,"subject":"Community Medicine","kind":"Calculation / interpretation","section":"Clinical Medicine"},{"n":126,"stem":"A health worker in a primary health centre is preparing to administer vaccines to infants. The cold chain temperature for storage of most EPI vaccines (BCG, OPV, DPT, Measles) in an ice-lined refrigerator (ILR) at the district level is:","options":{"A":"+2◦C to +4◦C","B":"+2◦C to +8◦C","C":"−15◦C to −25◦C","D":"0◦C to +2◦C"},"page":47,"subject":"Community Medicine","kind":"Concept / direct recall","section":"Clinical Medicine"},{"n":127,"stem":"A 10-year-old child from a rural area presents with brown discoloration of teeth (dental fluorosis) and skeletal deformities. On investigation, the community water supply shows a fluoride level of 3.5 mg/L. As per WHO and Indian standards, the permissible limit of fluoride in drinking water is:","options":{"A":"0.5 mg/L","B":"0.8 mg/L","C":"1.0 mg/L","D":"1.5 mg/L"},"page":48,"subject":"Community Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":128,"stem":"During a malaria surveillance programme in an endemic district, an entomologist collects adult mosquitoes from 100 houses and identifies 200 female Anopheles mosquitoes, of which 10 are found to be carrying Plasmodium falciparum sporozoites. The sporozoite rate and the most appropriate vector control measure for Anopheles culicifacies (the primary vector) in the indoor resting setting is:","options":{"A":"5%; larviciding with temephos","B":"5%; biological control with Gambusia fish","C":"10%; aerial spraying of malathion","D":"5%; indoor residual spraying (IRS) with DDT or synthetic pyrethroid"},"page":48,"subject":"Community Medicine","kind":"Concept / direct recall","section":"Clinical Medicine"},{"n":129,"stem":"A 35-year-old male labourer presents with cough for 3 weeks, evening fever, and haemoptysis. Sputum AFB smear is positive (2+). He is registered under Nikshay and started on Category I DOTS regimen. The intensive phase of Category I treatment under the National TB Elimination Programme (NTEP) consists of:","options":{"A":"2 months of HRZE (Isoniazid, Rifampicin, Pyrazinamide, Ethambutol)","B":"3 months of HRZ","C":"1 month of HRZES","D":"2 months of HR only"},"page":48,"subject":"Community Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":130,"stem":"The infant mortality rate (IMR) is one of the most sensitive indicators of the health status of a community. The formula for IMR per 1000 live births in a given year uses:","options":{"A":"Deaths under 1 year / Total population × 1000","B":"Deaths under 1 year / Total live births × 1000","C":"Deaths under 5 years / Total live births × 1000","D":"Deaths under 28 days / Total live births × 1000"},"page":49,"subject":"Community Medicine","kind":"Concept / direct recall","section":"Clinical Medicine"},{"n":131,"stem":"A 58-year-old male with a history of hypertension and diabetes presents to the emergency department with severe crushing chest pain radiating to the left arm for 90 minutes, diaphoresis, and nausea. Blood pressure is 100/70 mmHg, heart rate 98 bpm. ECG shows ST elevation of 3 mm in leads II, III, and aVF with reciprocal ST depression in leads I and aVL. Troponin I is 4.2 ng/mL (normal <0.04). The MOST appropriate immediate management is:","options":{"A":"Aspirin + Clopidogrel + IV heparin + transfer for primary PCI within 90 minutes","B":"Aspirin + IV morphine + IV furosemide + thrombolysis with streptokinase","C":"Aspirin + Clopidogrel + IV heparin + primary PCI within 120 minutes if door-to-balloon cannot be achieved within 90 min, else thrombolysis","D":"IV metoprolol + aspirin + atorvastatin + conservative management"},"page":49,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":132,"stem":"A 70-year-old woman with known ischaemic cardiomyopathy presents with worsening breathlessness on minimal exertion (NYHA class III), bilateral pitting pedal oedema up to the knee, and orthopnoea. Chest X-ray shows cardiomegaly, upper lobe diversion, and Kerley B lines. Echocardiography reveals EF 30%, dilated left ventricle. BNP is 1200 pg/mL. Which of the following medications has been shown to reduce mortality in this patient and is the drug of choice?","options":{"A":"Digoxin","B":"Loop diuretic (furosemide)","C":"Nitrates","D":"Sacubitril/Valsartan (ARNi)"},"page":49,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":133,"stem":"A 65-year-old male hypertensive presents with palpitations and breathlessness for 6 hours. The ECG strip below is obtained: Irregularly irregular rhythm, no distinct P waves His CHADS2-VASc score is 4. The MOST appropriate long-term management is:","options":{"A":"Rate control with metoprolol + anticoagulation with rivaroxaban","B":"Rhythm control with amiodarone only, no anticoagulation needed","C":"Aspirin alone for stroke prophylaxis","D":"DC cardioversion immediately without anticoagulation"},"page":50,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":134,"stem":"A 32-year-old woman with a history of recurrent sore throat in childhood presents with progressive exertional dyspnoea and occasional haemoptysis. On auscultation, the apex is tapping, there is a loud S1, an opening snap 60 ms after A2, and a low-pitched mid-diastolic rumble at the apex. ECG shows P-mitrale. Echocardiography reveals a mitral valve area of 0.9 cm2 with a mean gradient of 14 mmHg. The MOST appropriate intervention is:","options":{"A":"Long-term diuretic therapy with furosemide","B":"Balloon mitral valvotomy (BMV/PTMC)","C":"Mitral valve replacement with a mechanical prosthesis","D":"Beta-blocker therapy to control heart rate"},"page":50,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":135,"stem":"A 55-year-old male with a 10-year history of hypertension presents for review. Current BP is 162/98 mmHg on two readings 15 minutes apart. He has microalbuminuria (urine ACR 45 mg/g), serum creatinine 1.4 mg/dL, eGFR 58 mL/min/1.73m2, and no other comorbidities. The drug class that is MOST beneficial as first-line therapy in this patient with hypertension and early CKD:","options":{"A":"Thiazide diuretic (hydrochlorothiazide)","B":"Calcium channel blocker (amlodipine)","C":"ACE inhibitor (ramipril)","D":"Beta-blocker (atenolol)"},"page":51,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":136,"stem":"A 68-year-old retired teacher presents with 5-day history of productive cough with rusty sputum, right-sided pleuritic chest pain, fever (39.2◦C), and rigors. Examination reveals dullness to percussion, bronchial breath sounds, and increased vocal resonance over the right lower zone. CXR shows right lower lobe consolidation. WBC is 18,000/mm3 (neutrophilia), CRP 140 mg/L. Blood cultures are pending. CURB-65 score is 2. The MOST likely causative organism and MOST appropriate initial antibiotic are:","options":{"A":"Staphylococcus aureus; vancomycin IV","B":"Klebsiella pneumoniae; cefepime IV","C":"Legionella pneumophila; clarithromycin + rifampicin","D":"Streptococcus pneumoniae; amoxicillin-clavulanate or co-amoxiclav"},"page":51,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":137,"stem":"A 62-year-old male ex-smoker (40 pack-years) presents with progressive breathlessness, chronic cough with whitish sputum, and two hospitalizations in the past year. Spirometry shows FEV1/FVC ratio of 0.58 (post-bronchodilator), FEV1 = 42% predicted. The spirometry pattern is shown: Volume (L) Flow (L/s) Normal Obstructive FEV1 According to GOLD guidelines, this patient is classified as GOLD stage:","options":{"A":"GOLD 3 (Severe): FEV1 30–49% predicted","B":"GOLD 2 (Moderate): FEV1 50–79% predicted","C":"GOLD 4 (Very Severe): FEV1 <30% predicted","D":"GOLD 1 (Mild): FEV1 ≥80% predicted"},"page":51,"subject":"Medicine","kind":"Calculation / interpretation","section":"Clinical Medicine"},{"n":138,"stem":"A 45-year-old male presents with progressive breathlessness and rightsided dullness on percussion. Pleural fluid aspiration yields straw-coloured fluid. Investigations: Pleural fluid protein 4.8 g/dL, serum protein 6.5 g/dL; pleural fluid LDH 350 IU/L, serum LDH 280 IU/L; pleural fluid glucose 65 mg/dL. Applying Light’s criteria, this effusion is:","options":{"A":"Transudate — likely due to congestive heart failure","B":"Exudate — pleural fluid protein/serum protein ratio >0.5","C":"Transudate — pleural fluid LDH/serum LDH <0.6","D":"Exudate — pleural fluid glucose <60 mg/dL indicates malignancy"},"page":52,"subject":"Medicine","kind":"Calculation / interpretation","section":"Clinical Medicine"},{"n":139,"stem":"A 19-year-old college student with known bronchial asthma presents to the emergency department with acute severe attack: respiratory rate 28/min, SpO2 90% on room air, unable to complete sentences, PEFR 40% of predicted, using accessory muscles. She is already on low-dose ICS + SABA PRN. The MOST appropriate immediate treatment in the emergency department is:","options":{"A":"Double the dose of inhaled corticosteroid and discharge with spacer","B":"Start magnesium sulphate IV and discharge after 30 minutes","C":"Nebulised salbutamol + ipratropium, systemic corticosteroid, controlled oxygen (SpO2 target 93–95%), monitor for deterioration","D":"Intubate immediately and start mechanical ventilation"},"page":52,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":140,"stem":"A 42-year-old male presents with a 3-month history of epigastric pain that wakes him from sleep at 2 am, relieved by eating or antacids. Upper GI endoscopy reveals a 1.2 cm duodenal ulcer (D1). Rapid urease test (RUT) is positive. The MOST appropriate treatment is:","options":{"A":"Omeprazole alone for 8 weeks","B":"H2 blocker (ranitidine) for 4 weeks","C":"Sucralfate + antacids for 6 weeks","D":"Triple therapy: Omeprazole + Clarithromycin + Amoxicillin for 14 days"},"page":53,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":141,"stem":"A 26-year-old male presents with 8-month history of intermittent right lower quadrant colicky pain, non-bloody diarrhoea (5–6 stools/day), weight loss of 7 kg, and perianal fistula. Colonoscopy shows skip lesions, cobblestone appearance of mucosa, and strictures in the terminal ileum. Biopsy shows non-caseating granulomas. Which of the following is the MOST likely diagnosis?","options":{"A":"Crohn’s disease","B":"Ulcerative colitis","C":"Intestinal tuberculosis","D":"Ischaemic colitis"},"page":53,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":142,"stem":"A 50-year-old male with known alcoholic liver disease presents with massive haematemesis. Examination reveals spider naevi, palmar erythema, splenomegaly, and ascites. Serum bilirubin is 3.5 mg/dL, albumin 2.4 g/dL, prothrombin time prolonged by 5 seconds; grade II hepatic encephalopathy; moderate ascites. The Child-Pugh score places him in class:","options":{"A":"Child A (score 5–6), low surgical risk","B":"Child C (score ≥10), high surgical risk","C":"Child B (score 7–9), intermediate risk","D":"Cannot be calculated without LFT values"},"page":54,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":143,"stem":"A 38-year-old obese male with a history of alcohol binge presents with severe epigastric pain radiating to the back, nausea, and vomiting. Serum amylase is 1100 U/L (normal <100), lipase 2200 U/L. CT abdomen with contrast (CECT) is performed 48 hours after admission. Which of the following CT findings indicates severe acute pancreatitis with a high likelihood of pancreatic necrosis?","options":{"A":"Pancreatic oedema only (CT severity index 2)","B":"Peripancreatic fat stranding (CTSI 3)","C":">30% non-enhancement of pancreatic parenchyma with peripancreatic fluid collections (CTSI ≥7)","D":"Mild peri-pancreatic inflammation only (CTSI 4)"},"page":54,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":144,"stem":"A 60-year-old male undergoes emergency laparotomy for perforated viscus. Post-operatively he develops oliguria (<0.5 mL/kg/hr for 8 hours), serum creatinine rises from baseline 0.9 mg/dL to 3.6 mg/dL. Urine sodium is 8 mEq/L, serum sodium 140 mEq/L, urine creatinine 340 mg/dL, serum creatinine 3.6 mg/dL. The MOST likely cause and fractional excretion of sodium (FENa) are:","options":{"A":"Intra-renal AKI (acute tubular necrosis); FENa >2%","B":"Post-renal AKI (obstruction); FENa >2%","C":"Intra-renal AKI (acute tubular necrosis); FENa <1%","D":"Pre-renal AKI (hypovolaemia); FENa <1%"},"page":54,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":145,"stem":"A 55-year-old diabetic female is found to have serum creatinine 4.8 mg/dL, eGFR 14 mL/min/1.73m2, serum potassium 5.9 mEq/L, bicarbonate 16 mEq/L, Hb 7.8 g/dL, MCV 82 fL, serum ferritin 28 ng/mL, transferrin saturation 12%. The MOST appropriate treatment for her anaemia is:","options":{"A":"IV iron supplementation followed by erythropoiesis-stimulating agent (ESA) if Hb remains <10 g/dL","B":"Oral iron only","C":"Blood transfusion immediately","D":"ESA alone without iron"},"page":55,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":146,"stem":"A 28-year-old woman with SLE (ANA+, anti-dsDNA titre 1:640) develops worsening proteinuria (3.5 g/24 hours), serum albumin 2.1 g/dL, creatinine 1.8 mg/dL, and bilateral pitting pedal oedema. Renal biopsy shows diffuse proliferative glomerulonephritis with subendothelial immune deposits (wire loop lesions). This corresponds to:","options":{"A":"ISN/RPS Class II (mesangial proliferative lupus nephritis)","B":"ISN/RPS Class IV (diffuse proliferative lupus nephritis) — treat with high-dose steroids + cyclophosphamide or mycophenolate mofetil","C":"ISN/RPS Class V (membranous lupus nephritis)","D":"ISN/RPS Class III (focal proliferative lupus nephritis)"},"page":55,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":147,"stem":"A 72-year-old hypertensive male with known atrial fibrillation (not on anticoagulation) presents 1.5 hours after sudden onset of left-sided weakness (arm > leg), left facial droop, and expressive aphasia. BP 168/95 mmHg, blood glucose 110 mg/dL, INR 1.0. Non-contrast CT brain shows no haemorrhage, no early ischaemic changes. The MOST appropriate treatment is:","options":{"A":"Aspirin 300 mg immediately + clopidogrel","B":"Immediate heparin infusion","C":"IV alteplase (tPA) 0.9 mg/kg within the 4.5-hour window + anticoagulation after 24 hours","D":"Supportive care only; thrombolysis contraindicated in AF"},"page":55,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":148,"stem":"A 19-year-old college student presents with 48-hour history of severe headache, neck stiffness, photophobia, and non-blanching purpuric rash on the trunk and limbs. Temperature 39.8◦C. CSF analysis: opening pressure 300 mmH2O, appearance turbid, WBC 4000/mm3 (90% polymorphs), protein 280 mg/dL, glucose 28 mg/dL (blood glucose 90 mg/dL), Gram stain shows Gram-negative diplococci. The MOST likely organism and immediate treatment are:","options":{"A":"Streptococcus pneumoniae; cefotaxime + dexamethasone","B":"Listeria monocytogenes; ampicillin + gentamicin","C":"Cryptococcus neoformans; amphotericin B + flucytosine","D":"Neisseria meningitidis; IV benzylpenicillin or ceftriaxone + contact prophylaxis with rifampicin"},"page":56,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":149,"stem":"A 16-year-old girl has daily episodes of brief (<30 seconds) staring spells during which she is unresponsive, followed by immediate return to normal activity without post-ictal confusion. EEG shows 3 Hz generalised spike-and-wave discharges. She is currently not on any medication. The drug of choice for this seizure type is:","options":{"A":"Ethosuximide","B":"Carbamazepine","C":"Phenytoin","D":"Levetiracetam"},"page":56,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":150,"stem":"A 68-year-old retired engineer presents with a 3-year history of resting tremor in the right hand (pill-rolling), bradykinesia, rigidity, and shuffling gait with festination. Examination reveals masked facies, micrographia, and positive pull test. Cognition is intact. The MOST appropriate initial pharmacological treatment is:","options":{"A":"Donepezil","B":"Levodopa/Carbidopa","C":"Propranolol","D":"Haloperidol"},"page":56,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":151,"stem":"A 22-year-old male with Type 1 DM presents with 2-day history of vomiting, abdominal pain, polyuria, and confusion. Examination: Kussmaul breathing, fruity odour of breath, BP 90/60 mmHg, HR 120 bpm. Investigations: blood glucose 520 mg/dL, pH 7.12, bicarbonate 8 mEq/L, anion gap 24 mEq/L, serum ketones 4+, serum potassium 5.8 mEq/L. The MOST critical initial step in management (before insulin) is:","options":{"A":"Start insulin infusion at 0.1 U/kg/hr immediately","B":"Administer sodium bicarbonate to correct acidosis","C":"IV 0.9% normal saline fluid resuscitation (1–1.5 L in first hour)","D":"Give IV potassium 40 mEq/hr immediately"},"page":57,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":152,"stem":"A 38-year-old female presents with 6-month history of weight gain (8 kg), constipation, cold intolerance, menorrhagia, dry skin, and delayed ankle reflex relaxation. TSH is 42 mIU/L (normal 0.4–4.0), free T4 is 0.4 ng/dL (normal 0.8–1.8), anti-TPO antibody 320 IU/mL (positive). The treatment of choice and target TSH during replacement therapy are:","options":{"A":"Liothyronine (T3) alone; target TSH 0.1–0.5 mIU/L","B":"Carbimazole; target TSH <0.1 mIU/L","C":"Propylthiouracil (PTU) + iodine","D":"Levothyroxine (T4); target TSH 0.5–2.5 mIU/L"},"page":57,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":153,"stem":"A 35-year-old male presents with 6-month history of progressive fatigue, weight loss, hyperpigmentation of skin creases, buccal mucosa and surgical scars, postural hypotension (BP 100/60 supine, 80/50 standing), hyponatraemia (Na 128 mEq/L), and hyperkalaemia (K 5.8 mEq/L). Short synacthen test (ACTH stimulation) shows a peak cortisol of 12 mcg/dL at 30 minutes (normal >18). The MOST likely diagnosis and treatment are:","options":{"A":"Primary adrenal insufficiency (Addison’s disease); hydrocortisone + fludrocortisone","B":"Secondary adrenal insufficiency (pituitary); hydrocortisone only (no mineralocorticoid needed)","C":"Cushing’s syndrome; metyrapone","D":"Conn’s syndrome; spironolactone"},"page":57,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":154,"stem":"A 25-year-old pregnant woman (G2P1) at 28 weeks gestation has Hb 8.2 g/dL, MCV 65 fL, MCH 19 pg, serum ferritin 6 ng/mL, TIBC 480 mcg/dL. Peripheral smear shows microcytic hypochromic red cells with pencil cells and occasional target cells. Her previous child had thalassaemia trait. Mentzer index (MCV/RBC count) = 12. The MOST likely diagnosis and the confirmatory test are:","options":{"A":"Anaemia of chronic disease; serum EPO level","B":"Iron deficiency anaemia; serum ferritin + TIBC (already diagnostic)","C":"Thalassaemia trait; HPLC for haemoglobin analysis","D":"Sideroblastic anaemia; bone marrow biopsy"},"page":58,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":155,"stem":"A 22-year-old female presents with photosensitive butterfly-shaped facial rash, oral ulcers, polyarthralgia, and haematuria. Investigations: ANA 1:640 (homogeneous pattern), anti-dsDNA positive, complement C3 low, urine protein 2.0 g/24 hr, serum creatinine 1.6 mg/dL, haemoglobin 9.4 g/dL (Coombs positive). Direct Coombs test is positive. She fulfils SLICC 2012 criteria. The haematological feature in this patient that contributes to the SLICC score is:","options":{"A":"Thrombocytopenia (<100,000)","B":"Leukopenia (<4000)","C":"Autoimmune haemolytic anaemia (Coombs positive)","D":"Lymphopenia (<1000)"},"page":58,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":156,"stem":"A 40-year-old female with an 8-year history of seropositive rheumatoid arthritis (RF+, anti-CCP 320 U/mL) has failed methotrexate (20 mg/week) + leflunomide combination at 6 months. She has active disease (DAS28 5.8, swollen joint count 12/28, CRP 42 mg/L). The NEXT step in management according to EULAR guidelines is:","options":{"A":"Add hydroxychloroquine to the existing regimen","B":"Switch to sulfasalazine + hydroxychloroquine triple therapy","C":"Increase methotrexate to maximum dose (25 mg/week) and wait another 6 months","D":"Add a biologic DMARD (TNF-alpha inhibitor such as etanercept or adalimumab) or JAK inhibitor (tofacitinib)"},"page":59,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":157,"stem":"A 52-year-old male presents with an acute attack of severe pain, swelling, and erythema of the right first metatarsophalangeal joint (podagra) for 24 hours. Serum uric acid is 9.8 mg/dL. Synovial fluid analysis reveals negatively birefringent needle-shaped crystals under polarised light. He has a history of two previous similar attacks and has tophi over both Achilles tendons. The MOST appropriate acute treatment followed by long-term urate-lowering therapy (ULT) target is:","options":{"A":"NSAIDs (indomethacin) or colchicine for acute attack; allopurinol for ULT with target serum uric acid <6 mg/dL","B":"Aspirin for acute attack; febuxostat for ULT","C":"IV methylprednisolone; no ULT needed if only two attacks","D":"Probenecid alone; no NSAID needed in acute phase"},"page":59,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":158,"stem":"A 30-year-old male HIV-positive patient (CD4 count 180 cells/mm3) presents with 3-week cough, night sweats, fever, and weight loss. CXR shows bilateral infiltrates and a right upper lobe cavity. Sputum AFB smear is negative ×3. The MOST appropriate NEXT diagnostic test to confirm TB is:","options":{"A":"Tuberculin skin test (Mantoux)","B":"Sputum GeneXpert MTB/RIF assay","C":"IGRA (Interferon-Gamma Release Assay) blood test","D":"Bronchoscopy with BAL for fungal culture only"},"page":59,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":159,"stem":"A 60-year-old patient is assessed for elevated JVP. The JVP waveform is shown below: Time Pressure a x v y In a patient with tricuspid regurgitation, the JVP waveform characteristically shows:","options":{"A":"Absent ‘a’ wave","B":"Cannon ‘a’ waves","C":"Prominent ‘cv’ wave with obliteration of ‘x’ descent","D":"Prominent ‘y’ descent with normal ‘a’ wave (Friedrich’s sign)"},"page":60,"subject":"Medicine","kind":"Visual / interpretation","section":"Clinical Medicine"},{"n":160,"stem":"A 48-year-old male of African origin with hypertension (BP 158/96) and no other comorbidities is started on a calcium channel blocker. The mechanism of action of amlodipine in lowering blood pressure is: Time (weeks) BP (mmHg) Target BP 120/80","options":{"A":"Blocks beta-1 receptors, reducing cardiac output","B":"Inhibits ACE, reducing angiotensin II production","C":"Blocks alpha-1 receptors, causing vasodilatation","D":"Blocks L-type voltage-gated calcium channels in vascular smooth muscle, causing vasodilatation and reduced peripheral vascular resistance"},"page":60,"subject":"Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":161,"stem":"A 21-year-old male college student is brought by his family with a 6month history of social withdrawal, talking to himself, believing that his neighbours are conspiring to harm him (persecutory delusions), and hearing voices commenting on his actions (third-person auditory hallucinations). He is not on any medications and has no history of drug use. His IQ is normal. The MOST likely diagnosis and drug of choice for first-episode psychosis are:","options":{"A":"Schizophrenia; atypical antipsychotic (risperidone or olanzapine)","B":"Bipolar disorder with psychotic features; lithium + haloperidol","C":"Delusional disorder; psychotherapy alone","D":"Brief psychotic disorder; observe and discharge"},"page":61,"subject":"Psychiatry","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":162,"stem":"A 30-year-old female has a history of two previous depressive episodes and now presents with a 2-week history of decreased need for sleep (3 hours and feeling rested), grandiose beliefs (believes she is a famous actress), pressured speech, flight of ideas, disinhibited behaviour, and spending large sums of money recklessly. She is not distressed. The MOST appropriate treatment for acute mania is:","options":{"A":"SSRIs (fluoxetine)","B":"Lithium or valproate + an antipsychotic (olanzapine/risperidone) for acute mania","C":"Benzodiazepine alone for 4 weeks","D":"ECT as first-line treatment"},"page":61,"subject":"Psychiatry","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":163,"stem":"A 45-year-old female schoolteacher presents with 8-week history of persistent low mood, anhedonia (loss of interest in activities she previously enjoyed), early morning awakening, diurnal variation (worse in the morning), psychomotor retardation, poor concentration, and passive suicidal ideation (\"life is not worth living\") without a specific plan. PHQ- 9 score is 18. The MOST appropriate initial treatment for moderateto-severe MDD is:","options":{"A":"CBT alone (no medication needed for moderate severity)","B":"Benzodiazepine for anxiety component first, then reassess","C":"SSRI (sertraline or escitalopram) + CBT combination; assess suicide risk and consider safety planning","D":"Electroconvulsive therapy (ECT) immediately"},"page":62,"subject":"Psychiatry","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":164,"stem":"A 28-year-old male presents with intrusive thoughts about contamination (ego-dystonic), spending 3 hours a day washing his hands (compulsive ritual) to neutralise anxiety. He recognises these thoughts as irrational. He has tried to resist but cannot. This causes significant occupational impairment. The defence mechanism that BEST describes the ritual of handwashing (undoing the contamination thought) is:","options":{"A":"Repression","B":"Projection","C":"Displacement","D":"Undoing"},"page":62,"subject":"Psychiatry","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":165,"stem":"A 40-year-old male chronic heavy drinker is admitted after abruptly stopping alcohol 36 hours ago. He presents with tremor, profuse sweating, tachycardia (HR 118 bpm), BP 158/96 mmHg, confusion, agitation, and generalised tonic-clonic seizure. The MOST appropriate pharmacological treatment for alcohol withdrawal and prevention of Wernicke’s encephalopathy is:","options":{"A":"IV thiamine (before glucose) + benzodiazepines (chlordiazepoxide or diazepam) using symptom-triggered or fixed-schedule regimen","B":"Haloperidol + IV glucose only","C":"Naltrexone for craving reduction immediately","D":"Disulfiram starting within 24 hours of last drink"},"page":62,"subject":"Psychiatry","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":166,"stem":"An 80-year-old male with known moderate Alzheimer’s disease is admitted to hospital following a hip fracture. On the 2nd post-operative day, his family notices he is more confused, agitated at night (sundowning), with fluctuating consciousness, inattention, and visual hallucinations (seeing people in the room). His pre-admission cognitive baseline was mild-to-moderate decline. The feature MOST consistent with superimposed delirium (rather than dementia progression) is: Dementia Delirium Gradual onset Stable course Alert Acute onset Fluctuating Reduced attention","options":{"A":"Gradually progressive memory loss over 2 years","B":"Acute onset with fluctuating consciousness and inattention","C":"Presence of language difficulties (aphasia)","D":"Personality change over years"},"page":63,"subject":"Psychiatry","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":167,"stem":"A 55-year-old male, recently separated, unemployed, with a history of two previous suicide attempts (one involving a serious method), presents with hopelessness, a specific plan (he has saved up medications), and states he has \"nothing to live for.\" He drinks heavily (1 bottle/day). Based on established suicide risk factors, the MOST appropriate immediate action is:","options":{"A":"Provide outpatient counselling and safety contract; send home with family","B":"Prescribe an antidepressant and review in 1 week","C":"Admit to inpatient psychiatric unit for observation and safety (voluntary or involuntary); remove access to means; initiate treatment","D":"Refer for CBT; no immediate hospitalisation needed"},"page":63,"subject":"Psychiatry","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":168,"stem":"A 32-year-old IT professional presents with recurrent episodes of suddenonset palpitations, chest tightness, shortness of breath, dizziness, trembling, and an overwhelming fear of dying that peaks within 10 minutes and then gradually subsides. Between episodes, he worries constantly about having another attack and has started avoiding public transport. Cardiac evaluation including Holter monitoring is normal. The MOST likely diagnosis and first-line pharmacotherapy are:","options":{"A":"Generalised anxiety disorder; buspirone","B":"Social phobia; beta-blockers (atenolol)","C":"Specific phobia; systematic desensitisation","D":"Panic disorder; SSRI (paroxetine or escitalopram) + CBT (panicfocused)"},"page":64,"subject":"Psychiatry","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":169,"stem":"A 30-year-old male from rural Bihar presents with hypo-pigmented anaesthetic patches over the trunk, right ulnar nerve thickening with clawing of the 4th and 5th fingers (ulnar claw hand), and right common peroneal nerve thickening causing foot drop. Skin biopsy shows foamy macrophages loaded with acid-fast bacilli. The diagram below shows the commonly enlarged nerves in leprosy: Post. Auricular Ulnar N. Median N. Radial Cutaneous Common Peroneal Sural N. Commonly thickened nerves (red = most common) The leprosy type in this patient (foamy macrophages, high bacillary load) is:","options":{"A":"Lepromatous leprosy (LL) — multibacillary, poor cell-mediated immunity","B":"Tuberculoid leprosy (TT) — paucibacillary, strong CMI","C":"Borderline lepromatous (BL)","D":"Pure neuritic leprosy"},"page":64,"subject":"Psychiatry","kind":"Visual / interpretation","section":"Clinical Medicine"},{"n":170,"stem":"A 35-year-old male presents with well-defined erythematous plaques with silvery-white scales over the elbows, knees, and scalp for the past 2 years. Auspitz sign is positive. Nail examination shows pitting, onycholysis, and oil-drop sign. PASI score is 18. The FIRST-LINE treatment for extensive plaque psoriasis (PASI >10) in an outpatient setting is:","options":{"A":"Topical betamethasone alone indefinitely","B":"Systemic methotrexate (MTX) 10–25 mg/week + folic acid 5 mg/week; monitor LFTs","C":"Biologics (adalimumab) as first-line","D":"Cyclosporine A without prior phototherapy"},"page":65,"subject":"Psychiatry","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":171,"stem":"A 45-year-old female presents with painful oral erosions for 3 months, followed by the development of flaccid blisters over the trunk and back that rupture easily leaving raw erosive areas. Nikolsky sign is positive. Biopsy shows suprabasal acantholysis. Direct immunofluorescence (DIF) reveals net-like (fishnet) IgG and C3 deposits around epidermal cells. The MOST likely diagnosis and autoantibody are:","options":{"A":"Bullous pemphigoid; anti-BP180 (anti-BPAG2) antibody","B":"Dermatitis herpetiformis; IgA anti-endomysial antibody","C":"Pemphigus vulgaris; anti-desmoglein 3 (anti-Dsg3) IgG antibody","D":"Linear IgA bullous dermatosis; IgA antibody"},"page":65,"subject":"Dermatology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":172,"stem":"A 28-year-old male started on carbamazepine for epilepsy 3 weeks ago presents with fever, painful red erosions of the mouth, eyes (conjunctival injection), and genitalia, with extensive skin detachment. Nikolsky sign is positive. BSA skin detachment is approximately 35%. This is:","options":{"A":"Stevens-Johnson Syndrome (SJS) — BSA detachment <10%","B":"Erythema multiforme major — target lesions, <10% BSA","C":"Drug Reaction with Eosinophilia and Systemic Symptoms (DRESS)","D":"Toxic Epidermal Necrolysis (TEN) — BSA detachment >30%; treat in burns ICU, withdraw causative drug, supportive care; consider IVIG or cyclosporine"},"page":65,"subject":"Dermatology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":173,"stem":"A 7-year-old child presents with intensely pruritic lesions, worse at night, involving the web spaces of fingers, wrists, axillae, and genitalia. Several family members have similar complaints. Dermoscopy reveals a triangular dark structure at the end of a burrow (“delta wing jet” sign of the mite). The drug of choice and correct treatment protocol are:","options":{"A":"Permethrin 5% cream applied from neck down; leave for 8–12 hours; repeat after 1 week; treat all household contacts simultaneously","B":"Topical ivermectin 1% only; repeat daily for 5 days","C":"Benzyl benzoate 25% in children without dilution","D":"Oral doxycycline for 14 days"},"page":66,"subject":"Dermatology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":174,"stem":"A 25-year-old male presents with a painless indurated ulcer (chancre) on the glans penis with bilateral non-tender inguinal lymphadenopathy. He gives history of unprotected sexual contact 3 weeks ago. VDRL is reactive (1:32), FTA-ABS is positive. Which of the following is the drug of choice for primary syphilis?","options":{"A":"Azithromycin 1 g single dose","B":"Benzathine penicillin G 2.4 million units IM single dose","C":"Doxycycline 100 mg BD for 14 days (only if penicillin allergy)","D":"Ceftriaxone 1 g IM daily for 10 days"},"page":66,"subject":"Dermatology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":175,"stem":"A 20-year-old female student presents with sharply demarcated chalkwhite depigmented patches over the face, dorsum of hands, and around the mouth, progressively enlarging over 2 years. Wood’s lamp examination shows bright white fluorescence. She is otherwise healthy. The pathogenesis of vitiligo involves:","options":{"A":"IgE-mediated mast cell degranulation","B":"Type II hypersensitivity (antibody-dependent cytotoxicity)","C":"Autoimmune destruction of melanocytes by CD8+ T cells and autoantibodies against tyrosinase","D":"Infectious destruction of melanocytes by a spirochaete"},"page":66,"subject":"Dermatology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":176,"stem":"A 4-year-old boy presents with recurrent itchy, erythematous, oozing patches over the cheeks, antecubital fossae, and popliteal fossae, present since infancy. His mother has bronchial asthma. IgE is elevated (480 IU/mL). Skin prick test positive to house dust mite. The MOST appropriate stepwise treatment for moderate atopic dermatitis in a child, according to international guidelines (NICE/ETFAD):","options":{"A":"Systemic corticosteroids (prednisolone) as first-line","B":"Topical tacrolimus (calcineurin inhibitor) only; avoid moisturisers","C":"Oral antihistamine alone","D":"Regular emollients (moisturisers) + mid-potency topical corticosteroid for flares; topical calcineurin inhibitor (tacrolimus/pimecrolimus) for face and flexures"},"page":67,"subject":"Dermatology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":177,"stem":"A 55-year-old male smoker presents with breathlessness and a chest Xray as schematically shown below: Heart Trachea Normal L. Lung RUL Opacity Trachea deviated to right (towards collapse) The CXR pattern (opacification of right upper zone, elevated right hilum, tracheal shift to the right) is MOST consistent with:","options":{"A":"Right upper lobe collapse (atelectasis)","B":"Right-sided pleural effusion","C":"Right upper lobe consolidation (pneumonia)","D":"Right-sided tension pneumothorax"},"page":67,"subject":"Dermatology","kind":"Visual / interpretation","section":"Clinical Medicine"},{"n":178,"stem":"A 65-year-old male presents with sudden onset headache (\"worst headache of my life\") and neck stiffness. CT brain (non-contrast) is performed within 2 hours of onset. The MOST sensitive CT finding in the first 6 hours of subarachnoid haemorrhage (SAH) is:","options":{"A":"Hypodense (dark) area in the basal cisterns","B":"Hyperdense (bright white) blood in the basal cisterns and subarachnoid spaces","C":"Midline shift to the left","D":"Ring-enhancing lesion with mass effect"},"page":68,"subject":"Dermatology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":179,"stem":"A 50-year-old female with known seafood allergy is scheduled for a contrast-enhanced CT scan of the abdomen. The radiologist prescribes pre-medication. Which of the following is the MOST appropriate premedication protocol to reduce the risk of contrast reaction?","options":{"A":"Antihistamine (chlorpheniramine) alone 1 hour before the procedure","B":"IV adrenaline (epinephrine) prophylactically before contrast injection","C":"Prednisolone 50 mg orally 13, 7, and 1 hours before the procedure + diphenhydramine 50 mg IM 1 hour before (ACR protocol)","D":"Avoid contrast entirely; MRI without contrast is equivalent"},"page":68,"subject":"Dermatology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":180,"stem":"A radiology department is reviewing annual radiation dose limits for staff. According to the Atomic Energy Regulatory Board (AERB) guidelines for radiation workers in India, the annual effective dose limit for occupational exposure (averaged over 5 consecutive years) is:","options":{"A":"5 mSv/year","B":"10 mSv/year","C":"15 mSv/year","D":"20 mSv/year"},"page":69,"subject":"Dermatology","kind":"Concept / direct recall","section":"Clinical Medicine"},{"n":181,"stem":"A 22-year-old tall, thin male presents with sudden onset right-sided chest pain and dyspnoea while at rest. He has no prior lung disease. CXR shows a visible pleural line with absent lung markings lateral to it on the right side; the right lung edge is 3 cm from the chest wall at the level of the hilum. Trachea is central, BP is normal. The MOST appropriate management for this primary spontaneous pneumothorax is:","options":{"A":"Needle aspiration or intercostal drain (ICD) if the pneumothorax is >2 cm (BTS guidelines) — drain for moderate/large","B":"Immediate thoracotomy","C":"100% oxygen only; observe for 4 hours and discharge","D":"Bilateral ICD insertion empirically"},"page":69,"subject":"Radiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":182,"stem":"A 45-year-old obese female presents with recurrent right upper quadrant colicky pain after fatty meals, nausea, and vomiting. Ultrasound of the abdomen shows hyperechoic foci in the gallbladder with posterior acoustic shadowing and movement with change of position. Gallbladder wall is 2 mm (normal). CBD diameter is 4 mm. The MOST likely diagnosis and the investigation of choice to confirm CBD stones (if bilirubin rises) are:","options":{"A":"Gallbladder carcinoma; CT abdomen with contrast","B":"Cholelithiasis (gallstones); MRCP (Magnetic Resonance Cholangiopancreatography) to evaluate CBD","C":"Acute cholecystitis; HIDA scan","D":"Porcelain gallbladder; plain X-ray abdomen"},"page":69,"subject":"Radiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":183,"stem":"A 68-year-old male with controlled hypertension (BP 136/84 on amlodipine), Type 2 DM (HbA1c 7.4%, on metformin), BMI 32, and no limitations in daily activities (able to climb 2 flights of stairs) is scheduled for elective laparoscopic cholecystectomy. His ECG shows normal sinus rhythm. His ASA Physical Status Classification is:","options":{"A":"ASA I — no systemic disease","B":"ASA II — mild systemic disease, no functional limitation","C":"ASA III — severe systemic disease with functional limitation","D":"ASA IV — constant threat to life"},"page":70,"subject":"Radiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":184,"stem":"A 55-year-old patient receives rocuronium 1.2 mg/kg for rapid sequence intubation during emergency surgery. At end of surgery (60 minutes later), train-of-four (TOF) ratio is 0.2 (incomplete reversal). The MOST appropriate agent to reverse residual neuromuscular blockade from rocuronium is:","options":{"A":"Neostigmine + glycopyrrolate (anticholinesterase reversal)","B":"Edrophonium + atropine","C":"Atropine alone","D":"Sugammadex 4 mg/kg IV (encapsulates rocuronium; most complete reversal)"},"page":70,"subject":"Radiology","kind":"Calculation / interpretation","section":"Clinical Medicine"},{"n":185,"stem":"A patient undergoing inhalational induction with sevoflurane is observed to have the following signs: loss of consciousness, regular breathing, eyelash reflex absent, eyelid reflex present, pupils equal and mid-size, no response to verbal command, but still has laryngeal and pharyngeal reflexes intact (at risk of laryngospasm). According to Guedel’s stages of anaesthesia, this corresponds to: Stage I: Analgesia: Conscious responsive amnesia Stage II: Excitement: Irregular breathing risk of vomiting Stage III: Surgical: Regular breathing reflexes lost progressively Stage IV: Overdose: Respiratory arrest death Stage I: Analgesia Stage II: Excitement Stage III: Surgical Anaesthesia (Planes 1–4) Stage IV: Medullary depression","options":{"A":"Stage III, Plane 1 (surgical anaesthesia, laryngeal and pharyngeal reflexes still present)","B":"Stage I (analgesia — patient still conscious)","C":"Stage II (excitement — irregular breathing, risk of laryngospasm)","D":"Stage IV (medullary depression — respiratory arrest)"},"page":71,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":186,"stem":"A 40-year-old patient is being maintained on isoflurane for general anaesthesia. The concept of Minimum Alveolar Concentration (MAC) is used to compare potency of inhalational agents. Which of the following statements about MAC is CORRECT?","options":{"A":"MAC is the concentration that prevents movement in 95% of patients (EC95)","B":"MAC is the end-tidal concentration (in % atm) that prevents movement in 50% of patients in response to a standard surgical incision; higher MAC = lower potency","C":"MAC is independent of age, opioid premedication, and body temperature","D":"MAC of nitrous oxide is less than 1% (very potent)"},"page":71,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":187,"stem":"A 28-year-old primigravida undergoes spinal anaesthesia (intrathecal bupivacaine 2.5 mL of 0.5% heavy) for elective caesarean section. Twenty minutes after the block, she develops severe hypotension (BP 80/50 mmHg), nausea, and bradycardia (HR 52 bpm). The MOST likely cause and immediate treatment are:","options":{"A":"High spinal block causing diaphragm paralysis; intubation immediately","B":"Total spinal anaesthesia; 100% oxygen","C":"Sympathetic blockade causing aortocaval compression + vasodilation; left lateral tilt + IV ephedrine or phenylephrine + IV fluid bolus","D":"Post-dural puncture headache (PDPH); blood patch immediately"},"page":71,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":188,"stem":"A 24-year-old male receives succinylcholine + halothane for induction of anaesthesia for an emergency appendicectomy. Within 20 minutes, he develops masseter muscle rigidity, temperature rapidly rising (40.5◦C), tachycardia (HR 145 bpm), muscle rigidity, and mixed respiratory and metabolic acidosis on ABG. Serum CK is markedly elevated (12,000 IU/L). The MOST likely diagnosis and specific treatment are:","options":{"A":"Neuroleptic malignant syndrome; bromocriptine + dantrolene","B":"Thyroid storm; propylthiouracil + beta-blocker","C":"Serotonin syndrome; cyproheptadine","D":"Malignant hyperthermia; dantrolene sodium 2.5 mg/kg IV (up to 10 mg/kg) + stop triggering agents + cooling measures + correct acidosis"},"page":72,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":189,"stem":"A 32-year-old mountaineer at high altitude develops hyperventilation with a resulting respiratory alkalosis (pH 7.52, PaCO2 28 mmHg). The effect on the oxygen-haemoglobin dissociation curve is shown below: PaO2 (mmHg) SaO2 (%) Normal Left shift 50% P50≈27 P50↓ The effect of respiratory alkalosis on the oxygen-haemoglobin dissociation curve and tissue oxygen delivery is:","options":{"A":"Left shift of the curve; haemoglobin binds oxygen more avidly, P50 decreases, tissue oxygen unloading is reduced (Bohr effect)","B":"Right shift; haemoglobin releases oxygen more readily, P50 increases","C":"No shift; P50 unchanged by pH changes","D":"Left shift; tissue oxygenation is improved (increased oxygen release)"},"page":72,"subject":"Anaesthesiology","kind":"Visual / interpretation","section":"Clinical Medicine"},{"n":190,"stem":"A 65-year-old male with severe COPD (FEV1 38% predicted) is scheduled for transurethral resection of the prostate (TURP). The anaesthetist prefers neuraxial anaesthesia. Comparing spinal and epidural anaesthesia for this patient, which statement is CORRECT?","options":{"A":"Epidural anaesthesia has a faster onset than spinal","B":"Spinal anaesthesia has a faster, more predictable onset and denser block; epidural allows continuous dosing via catheter and titration; both avoid general anaesthesia and its risks in COPD","C":"Spinal anaesthesia is contraindicated with INR <1.2","D":"Epidural is always preferred over spinal for TURP because of TURP syndrome risk"},"page":73,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":191,"stem":"A 32-year-old female (non-smoker, history of motion sickness) undergoes laparoscopic surgery under general anaesthesia with volatile agent and opioid analgesia. Post-operatively, she develops severe nausea and vomiting (PONV) despite standard prophylaxis with ondansetron. Her Apfel score is 4 (all four risk factors present). The drug mechanism of ondansetron and a rescue antiemetic with a different mechanism are:","options":{"A":"Ondansetron: D2 receptor antagonist; rescue: granisetron","B":"Ondansetron: NK1 receptor antagonist; rescue: aprepitant","C":"Ondansetron: 5-HT3 receptor antagonist; rescue: haloperidol (D2 antagonist) or dexamethasone","D":"Ondansetron: H1 receptor antagonist; rescue: cyclizine"},"page":73,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":192,"stem":"A 65-year-old diabetic male with CKD (eGFR 35 mL/min/1.73m2, serum creatinine 2.1 mg/dL) requires an urgent contrast-enhanced CT scan. The MOST important preventive measure against contrast-induced nephropathy (CIN) is:","options":{"A":"Administer acetylcysteine 600 mg BD for 2 days (only)","B":"Stop metformin 48 hours before (only measure needed)","C":"Use high-osmolar contrast (ionic) media as it is more stable","D":"Pre-procedure IV isotonic saline hydration (1 mL/kg/hr for 3–12 hours before and after), use iso-osmolar or low-osmolar non-ionic contrast, minimise contrast volume, hold metformin"},"page":74,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":193,"stem":"A 35-year-old male presents with sudden-onset severe epigastric pain that has now shifted to the right iliac fossa over 12 hours. He has rebound tenderness and guarding at McBurney’s point. Temperature is 38.2◦C, WBC 16,500/mm3 (neutrophilia). Rovsing’s sign is positive. Alvarado score is 8. The MOST likely diagnosis and treatment are:","options":{"A":"Acute appendicitis; laparoscopic appendicectomy","B":"Perforated peptic ulcer; laparotomy","C":"Acute mesenteric ischaemia; CT angiography","D":"Renal colic; IV analgesia + ureteric stenting"},"page":74,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":194,"stem":"A 2-year-old child from a food-insecure household presents with bilateral pitting pedal oedema, sparse depigmented hair that plucks easily (flag sign), flaky-paint dermatosis, hepatomegaly, and a miserable expression (not interested in surroundings). His weight-for-age Z-score is –3. Serum albumin is 1.8 g/dL. The MOST likely diagnosis and distinguishing feature from marasmus are:","options":{"A":"Marasmus; absent oedema, severe wasting (bag of bones appearance)","B":"Kwashiorkor; presence of nutritional oedema, hypoalbuminaemia, adequate calorie intake with protein deficiency","C":"Marasmic kwashiorkor; the child is too thin to have kwashiorkor","D":"Nutritional rickets; bowing of legs is the hallmark"},"page":75,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":195,"stem":"During a foodborne outbreak in a wedding function attended by 300 guests, cases of acute gastroenteritis (vomiting, diarrhoea, abdominal cramps) were reported. The epidemic curve (bar chart of cases by hour of onset) is shown below: Hours after meal No. of cases Peak: 4–5 hrs The epidemic curve pattern (sharp single peak, rapid rise and fall within hours) is MOST consistent with:","options":{"A":"Propagated person-to-person epidemic","B":"Continuous common-source epidemic (prolonged exposure)","C":"Point-source common-vehicle epidemic (single-exposure event)","D":"Mixed epidemic pattern"},"page":75,"subject":"Community Medicine","kind":"Visual / interpretation","section":"Clinical Medicine"},{"n":196,"stem":"In the Universal Immunisation Programme (UIP) of India, which of the following correctly states the vaccine given at birth?","options":{"A":"BCG + OPV0 + Hepatitis B (birth dose) + Vitamin K","B":"OPV0 + DPT only","C":"BCG + Rotavirus vaccine","D":"BCG + OPV0 + Hepatitis B birth dose (the three vaccines given at birth under UIP)"},"page":76,"subject":"Community Medicine","kind":"Concept / direct recall","section":"Clinical Medicine"},{"n":197,"stem":"A 5-year-old male child presents with recurrent episodes of haemarthrosis (joint bleeds), particularly involving the right knee, and prolonged bleeding after minor cuts. His parents are first cousins. PT is normal (13 seconds), aPTT is prolonged (72 seconds, control 32 seconds). Platelet count and bleeding time are normal. Factor VIII activity is 2% (severely reduced). The MOST likely diagnosis and specific treatment are:","options":{"A":"Haemophilia A; recombinant Factor VIII concentrate","B":"Haemophilia B; recombinant Factor IX concentrate","C":"von Willebrand disease; DDAVP (desmopressin)","D":"ITP (immune thrombocytopenic purpura); IV immunoglobulin"},"page":76,"subject":"Community Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":198,"stem":"A 28-year-old sexually active female presents with 3-day history of burning micturition, frequency, urgency, and suprapubic pain. She has no fever and no flank pain. Urinalysis shows leucocytes 3+, nitrites positive, no casts. Urine culture is pending. She has no prior UTI in the past 6 months and no anatomical abnormality. The MOST appropriate treatment is:","options":{"A":"IV ceftriaxone for 14 days (complicated UTI)","B":"Nitrofurantoin 100 mg BD for 5 days OR trimethoprim-sulfamethoxazole for 3 days (uncomplicated lower UTI)","C":"Ciprofloxacin for 14 days (treat as pyelonephritis)","D":"No treatment; self-limiting condition; increase fluid intake only"},"page":76,"subject":"Community Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":199,"stem":"A 35-year-old female presents with new-onset relapsing-remitting neurological symptoms including transient visual loss (optic neuritis), upper limb weakness, and sensory disturbances. An MRI brain and spine with gadolinium is ordered. The MOST specific MRI finding that supports a diagnosis of multiple sclerosis (MS) is:","options":{"A":"Single enhancing lesion in the cerebellum","B":"Diffuse cortical atrophy","C":"Multiple periventricular T2/FLAIR hyperintense lesions (Dawson’s fingers) with lesions disseminated in space and time; one or more Gd-enhancing lesions","D":"Basal ganglia T1 hyperintense lesions"},"page":77,"subject":"Community Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":200,"stem":"A 50-year-old female undergoes open abdominal hysterectomy under general anaesthesia. On Day 1 post-operatively, she reports pain score 8/10. The anaesthetist plans multimodal analgesia. Which of the following regimens BEST represents the multimodal approach to reduce opioid requirements (opioid-sparing) and side effects?","options":{"A":"IV morphine PCA (patient-controlled analgesia) alone","B":"IV paracetamol alone (regular 4-hourly)","C":"IM diclofenac PRN only","D":"Regular paracetamol IV + NSAID (ketorolac or diclofenac) + epidural or local anaesthetic wound infiltration + low-dose opioid PRN for breakthrough pain & Specialties (Q 201–300)"},"page":77,"subject":"Community Medicine","kind":"Clinical vignette","section":"Clinical Medicine"},{"n":201,"stem":"A 38-year-old woman presents with a midline anterior neck swelling that has been enlarging over 6 months. On examination, the swelling moves upward on swallowing. She has no voice change, dysphagia, or pressure symptoms. Serum TSH is normal. The surgeon plans a total thyroidectomy. During surgery, the structure MOST at risk of injury that would cause hoarseness of voice is: Isthmus RLN Sup. thyroid a. PTH Thyroid Surgical Anatomy Sup. thyroid a.","options":{"A":"Recurrent laryngeal nerve","B":"External branch of superior laryngeal nerve","C":"Internal branch of superior laryngeal nerve","D":"Superior thyroid artery"},"page":77,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":202,"stem":"A 52-year-old man presents with a painless, hard thyroid nodule. FNAC shows cells with ground-glass nuclei, nuclear grooves, and psammoma bodies. Family history is negative. Serum calcitonin is normal. Which is the MOST likely histological type of thyroid carcinoma?","options":{"A":"Follicular carcinoma","B":"Papillary carcinoma","C":"Medullary carcinoma","D":"Anaplastic carcinoma"},"page":78,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":203,"stem":"A 48-year-old woman is diagnosed with invasive ductal carcinoma of the right breast. Tumour size is 4 cm, 4 ipsilateral axillary lymph nodes are positive for metastasis, and chest CT shows no distant metastases. According to TNM staging, what is the MOST likely stage?","options":{"A":"Stage IIA","B":"Stage IIB","C":"Stage IIIA","D":"Stage IIIB"},"page":78,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":204,"stem":"A 40-year-old woman presents with a 2 cm discrete, mobile, firm lump in the left breast. FNAC is performed. The cytology report shows Grade C5 findings. This grading is MOST consistent with:","options":{"A":"Benign — fibroadenoma","B":"Atypical cells, possibly malignant","C":"Suspicious of malignancy","D":"Definite malignancy"},"page":79,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":205,"stem":"A 55-year-old woman undergoes modified radical mastectomy for carcinoma of the right breast. Two weeks post-operatively she develops painless, fluctuant, non-erythematous swelling in the axilla. The MOST likely complication is:","options":{"A":"Seroma","B":"Wound haematoma","C":"Wound dehiscence","D":"Lymphangitis"},"page":79,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":206,"stem":"A 22-year-old man presents with a 24-hour history of periumbilical pain migrating to the right iliac fossa, nausea, and low-grade fever (37.8◦C). On examination: Rovsing’s sign positive, McBurney’s point tenderness, and guarding. WBC is 14,500/µL with a left shift. The MOST appropriate NEXT step in management is:","options":{"A":"CT abdomen and pelvis with contrast","B":"Observation and serial abdominal examinations","C":"Emergency appendicectomy","D":"Colonoscopy"},"page":79,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":207,"stem":"A 65-year-old man presents with colicky abdominal pain, absolute constipation, abdominal distension, and vomiting for 3 days. He had a previous laparotomy for peptic ulcer perforation 10 years ago. X-ray abdomen supine shows multiple air-fluid levels with central ladder-pattern loops. The MOST common cause of this presentation is:","options":{"A":"Carcinoma of the colon","B":"Femoral hernia","C":"Adhesions from prior surgery","D":"Volvulus of the sigmoid colon"},"page":79,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":208,"stem":"A 58-year-old man with no family history of colorectal cancer presents for routine check-up. He is asymptomatic. According to current screening guidelines for average-risk individuals, the MOST appropriate primary screening method to recommend at his age is:","options":{"A":"Annual digital rectal examination alone","B":"Flexible sigmoidoscopy every 5 years","C":"Annual faecal occult blood test (FOBT)","D":"Colonoscopy every 10 years"},"page":80,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":209,"stem":"A 35-year-old man presents with a right inguinal bulge appearing on straining. On examination, the swelling appears medial to the inferior epigastric vessels and does not descend into the scrotum. The deep inguinal ring is unoccupied. This hernia type passes through which anatomical structure? Inguinal ligament Hesselbach’s Inf. epigastric v. Deep ring Superficial ring Inguinal Canal Anatomy Indirect →deep ring; Direct →Hesselbach’s","options":{"A":"Deep inguinal ring","B":"Femoral canal","C":"Hesselbach’s triangle (posterior wall of inguinal canal)","D":"Superficial inguinal ring only"},"page":80,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":210,"stem":"A 60-year-old multiparous woman presents with a small, tense, irreducible lump in the upper medial thigh just below and lateral to the pubic tubercle. It appeared 2 days ago and is associated with severe colicky abdominal pain and vomiting. The MOST likely diagnosis is:","options":{"A":"Inguinal lymphadenopathy","B":"Strangulated femoral hernia","C":"Obturator hernia","D":"Saphena varix"},"page":81,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":211,"stem":"A 30-year-old man presents with sudden onset severe generalised abdominal pain, board-like rigidity, and absent bowel sounds. He gives a 6-year history of epigastric pain relieved by antacids. Erect chest Xray shows free air under both hemidiaphragms. The MOST appropriate immediate management is:","options":{"A":"IV proton pump inhibitor and nasogastric decompression","B":"H. pylori eradication therapy and close observation","C":"Emergency laparotomy with peritoneal lavage","D":"Endoscopy under sedation to identify the source"},"page":81,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":212,"stem":"A 45-year-old obese woman presents with right upper quadrant pain radiating to the right shoulder tip, nausea, and fever (38.5◦C) for 18 hours. On examination: Murphy’s sign positive. LFT shows ALP 280 U/L, bilirubin 1.8 mg/dL, ALT 65 U/L. WBC 13,200/µL. The BEST initial investigation to confirm the diagnosis is:","options":{"A":"CT abdomen with contrast","B":"HIDA (hepatobiliary iminodiacetic acid) scan","C":"MRCP (magnetic resonance cholangiopancreatography)","D":"Ultrasound of the abdomen"},"page":81,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":213,"stem":"A 55-year-old woman with known gallstones presents with Charcot’s triad: right upper quadrant pain, jaundice, and fever with rigors. Total bilirubin is 8.2 mg/dL; ALP is 520 U/L; GGTP is elevated. Ultrasound shows dilated CBD (12 mm). The MOST appropriate NEXT step in management is:","options":{"A":"ERCP with sphincterotomy and stone extraction","B":"Urgent open cholecystectomy","C":"Percutaneous transhepatic cholangiography (PTC)","D":"MRCP for further delineation only"},"page":81,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":214,"stem":"A 48-year-old alcoholic man presents with haematemesis. On examination: splenomegaly, ascites, caput medusae, and jaundice. Upper GI endoscopy reveals large oesophageal varices (Grade III) with active bleeding. The MOST effective immediate pharmacological measure to control variceal bleeding is:","options":{"A":"Propranolol","B":"Terlipressin (vasopressin analogue)","C":"Spironolactone","D":"Omeprazole IV infusion"},"page":82,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":215,"stem":"A 62-year-old man presents with painless progressive jaundice, significant weight loss (8 kg in 3 months), and a palpable, non-tender, distended gallbladder. Total bilirubin is 18 mg/dL; ALP is 900 U/L. CA 19-9 is elevated. CT scan shows a mass at the head of pancreas with dilated biliary tree. This clinical picture (palpable gallbladder + painless jaundice) is described by which eponymous sign?","options":{"A":"Charcot’s sign","B":"Grey Turner’s sign","C":"Courvoisier’s sign","D":"Trousseau’s sign"},"page":82,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":216,"stem":"A 42-year-old man presents with dilated, tortuous superficial veins in the left lower leg, aching, heaviness, and occasional swelling. The Trendelenburg test (tourniquet test) is positive when the tourniquet is placed at the saphenofemoral junction level. The MOST likely primary site of incompetence is: GSV Perfs. SFJ Tourniquet Trendelenburg Test","options":{"A":"Short saphenous vein at saphenopopliteal junction","B":"Perforator veins of the lower leg (Cockett’s perforators)","C":"Deep femoral vein valvular incompetence","D":"Saphenofemoral junction (SFJ) incompetence"},"page":82,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":217,"stem":"A 55-year-old woman who underwent total hip replacement 5 days ago develops swelling, redness, warmth, and pitting oedema of the left calf. Homan’s sign is equivocal. Her Wells score is 3 (high probability). The BEST diagnostic investigation to confirm deep vein thrombosis is:","options":{"A":"Compression duplex ultrasonography","B":"D-dimer assay","C":"Venography","D":"CT pulmonary angiography"},"page":83,"subject":"Surgery","kind":"Calculation / interpretation","section":"Surgery & Specialties"},{"n":218,"stem":"A 65-year-old diabetic smoker presents with calf pain on walking 200 metres, relieved by rest. ABI (ankle-brachial index) is 0.55. On examination: absent popliteal pulse bilaterally, dependent rubor. This symptom is classified under which Fontaine stage?","options":{"A":"Fontaine Stage I — asymptomatic","B":"Fontaine Stage IIb — claudication at < 200 m","C":"Fontaine Stage III — rest pain","D":"Fontaine Stage IV — ulceration/gangrene"},"page":83,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":219,"stem":"A 72-year-old hypertensive man presents with sudden severe tearing abdominal and back pain. On examination: pulsatile expansile midline abdominal mass, BP 90/60 mmHg, HR 120/min, pallor. The MOST appropriate immediate management is:","options":{"A":"CT angiography of the aorta urgently","B":"IV fluids resuscitation and urgent vascular surgery review","C":"Emergency open surgical repair","D":"Endovascular aortic repair (EVAR) electively"},"page":84,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":220,"stem":"A 60-year-old obese diabetic man who underwent elective colectomy develops a serosanguinous discharge from his midline laparotomy wound on post-operative day 7. On examination, bowel loops are visible through the wound edges. This complication is described as:","options":{"A":"Wound seroma","B":"Wound haematoma","C":"Anastomotic leak","D":"Burst abdomen (complete wound dehiscence with evisceration)"},"page":84,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":221,"stem":"A 55-year-old man with operable rectal carcinoma undergoes pre-operative staging. MRI pelvis shows the tumour is 5 cm from the anal verge, invades muscularis propria but not beyond, with one positive mesorectal lymph node, and no distant metastases. According to TNM staging, this is MOST likely:","options":{"A":"T2N1M0 — Stage IIIA","B":"T3N0M0 — Stage IIA","C":"T4aN1M0 — Stage IIIC","D":"T2N0M0 — Stage I"},"page":84,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":222,"stem":"A 50-year-old man undergoes Hartmann’s procedure for perforated sigmoid diverticulitis. The resultant stoma is a sigmoid colostomy. Compared to an ileostomy, which of the following features is MOST characteristic of a colostomy? Colostomy Ileostomy Spout Flush Formed stool Liquid/semi-liquid Low irritant High irritant Colostomy vs Ileostomy","options":{"A":"Raised spout (to protect skin from caustic effluent)","B":"Flush with the skin, producing formed stool","C":"Higher output (>500 mL/day) with severe electrolyte imbalance","D":"Located in the right iliac fossa typically"},"page":84,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":223,"stem":"A 26-year-old primigravida at 10 weeks of gestation attends her first antenatal visit. Routine blood investigations are performed. Which of the following is NOT routinely offered at the first antenatal visit?","options":{"A":"Blood group and Rh typing","B":"VDRL for syphilis screening","C":"Glucose challenge test (GCT) for gestational diabetes","D":"HIV testing with counselling"},"page":85,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":224,"stem":"A 32-year-old woman at 34 weeks of gestation presents with sudden onset of painless, bright red vaginal bleeding. There is no uterine tenderness. FHR tracing is reassuring. On USS, placenta is seen covering the internal os completely. The MOST appropriate immediate management is: Fetus Internal os Placenta (Grade IV) Placenta Praevia Grades Grade I: Low Grade II: Marginal Grade III: Partial Grade IV: Central","options":{"A":"Immediate digital vaginal examination to assess cervix","B":"Induction of labour with oxytocin","C":"Tocolysis with nifedipine and close monitoring","D":"Hospitalisation, bed rest, IV access, crossmatch, and plan for LSCS"},"page":85,"subject":"Surgery","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":225,"stem":"A 28-year-old primigravida at 36 weeks presents with severe headache, visual disturbances, and epigastric pain. BP is 170/115 mmHg. Urinalysis shows 3+ proteinuria. Platelet count is 75,000/µL; ALT 120 U/L; LDH 800 U/L. The MOST appropriate immediate treatment to prevent seizures is:","options":{"A":"Magnesium sulphate IV","B":"Oral phenobarbitone","C":"IV diazepam","D":"Oral nifedipine alone"},"page":86,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":226,"stem":"A 30-year-old woman at 26 weeks of gestation undergoes a 75 g oral glucose tolerance test (OGTT) as part of routine screening. Her fasting plasma glucose is 4.8 mmol/L, 1-hour value is 10.5 mmol/L, and 2-hour value is 8.8 mmol/L. According to IADPSG criteria, gestational diabetes mellitus is diagnosed when:","options":{"A":"Fasting ≥5.1 mmol/L or 1-hour ≥10.0 mmol/L or 2-hour ≥8.5 mmol/L","B":"Fasting ≥7.0 mmol/L or 2-hour ≥11.1 mmol/L","C":"1-hour ≥11.1 mmol/L alone","D":"Any random glucose ≥11.1 mmol/L only"},"page":86,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":227,"stem":"A 24-year-old woman with a history of PID presents with sudden severe right iliac fossa pain, vaginal bleeding (spotting), and syncope. LMP was 6 weeks ago. BP 80/50 mmHg, HR 130/min. Urine βhCG is positive. Pelvic USS shows no intrauterine pregnancy and free fluid in the pouch of Douglas. The MOST appropriate NEXT step is:","options":{"A":"Administer methotrexate IM","B":"Serial βhCG monitoring over 48 hours","C":"Emergency laparotomy/laparoscopy","D":"Diagnostic laparoscopy under elective conditions"},"page":87,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":228,"stem":"A 38-year-old woman at 41 weeks of gestation is scheduled for induction of labour. Bishop score is assessed. Which of the following cervical parameters is NOT included in the Bishop score? Parameter Dilation Effacement Station Consistency Position Closed 1-2 3-4 5+ 0-30 40-50 60-70 80+ -3 -2 -1/0 +1/2 Firm Med Soft – Post Mid Ant – Bishop Score Components","options":{"A":"Cervical dilation","B":"Fetal station","C":"Cervical effacement","D":"Fetal heart rate pattern"},"page":87,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":229,"stem":"A 25-year-old primipara delivers a 3.8 kg baby vaginally. Twenty minutes after delivery, she has not delivered the placenta, and then develops torrential vaginal bleeding. Estimated blood loss is 900 mL. On examination: uterus is soft and boggy. BP 90/60 mmHg. The MOST common cause of primary postpartum haemorrhage is:","options":{"A":"Uterine atony","B":"Retained placenta","C":"Vaginal lacerations","D":"Coagulopathy"},"page":87,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":230,"stem":"A 22-year-old primigravida at term is in labour for 20 hours. Despite adequate uterine contractions, there is no progress of descent. On examination: cervix is fully dilated; fetal head is at 0 station; a Bandl’s ring is palpable. The MOST appropriate NEXT step is:","options":{"A":"Administer additional oxytocin","B":"Emergency caesarean section","C":"Vacuum-assisted delivery","D":"Symphysiotomy"},"page":88,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":231,"stem":"A 22-year-old woman presents with oligomenorrhoea, acne, hirsutism, and difficulty conceiving for 2 years. BMI is 28 kg/m2. USS shows bilateral ovarian enlargement with 12 follicles each measuring 2–9 mm arranged peripherally (necklace sign). LH:FSH ratio is 2.5. According to Rotterdam criteria, PCOS is diagnosed when at least two of three features are present. Which set MOST accurately reflects these criteria?","options":{"A":"Elevated LH, low FSH, and PCO morphology on USS","B":"Oligomenorrhoea alone with high androgens","C":"Oligo-anovulation, hyperandrogenism (clinical/biochemical), and PCO morphology on USS","D":"Infertility, obesity, and acne"},"page":88,"subject":"Obstetrics & Gynaecology","kind":"Calculation / interpretation","section":"Surgery & Specialties"},{"n":232,"stem":"A 35-year-old woman presents with heavy menstrual bleeding (HMB), dysmenorrhoea, and urinary frequency. On bimanual examination, the uterus is enlarged (14 weeks size), irregular, and non-tender. USS shows multiple intramural and subserosal myomas. Haemoglobin is 8.2 g/dL. The fibroid subtype MOST likely responsible for her heavy menstrual bleeding is:","options":{"A":"Subserosal fibroid","B":"Pedunculated fibroid","C":"Cervical fibroid","D":"Submucosal fibroid"},"page":88,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":233,"stem":"A 28-year-old woman presents with progressive dysmenorrhoea starting 2–3 days before menstruation, deep dyspareunia, and secondary infertility. On laparoscopy, powder-burn lesions (black deposits) are seen on the uterosacral ligaments and ovary. There is a 4 cm endometrioma in the left ovary. The MOST accurate diagnostic tool for endometriosis is:","options":{"A":"Diagnostic laparoscopy with histological confirmation","B":"Serum CA-125 level","C":"MRI of the pelvis","D":"Transvaginal ultrasound"},"page":89,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":234,"stem":"A 30-year-old sexually active woman attends for routine cervical screening. She has never had an abnormal smear. Current Indian/WHO guidelines for cervical cancer screening recommend which of the following as preferred primary screening method?","options":{"A":"Annual Pap smear from age 18","B":"HPV DNA testing (co-testing or primary HPV test) every 5 years from age 25–30","C":"Colposcopy every 2 years","D":"VIA (visual inspection with acetic acid) annually"},"page":89,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":235,"stem":"A 55-year-old postmenopausal woman presents with abdominal distension, bilateral adnexal masses, and ascites. CA-125 is 620 U/mL. CT abdomen-pelvis shows peritoneal deposits and omental caking. The MOST common histological type of ovarian carcinoma is:","options":{"A":"Mucinous cystadenocarcinoma","B":"Endometrioid carcinoma","C":"High-grade serous carcinoma","D":"Clear cell carcinoma"},"page":89,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":236,"stem":"A 42-year-old woman presents with irregular, heavy menstrual bleeding occurring at unpredictable intervals. There is no pelvic mass. Endometrial biopsy shows simple hyperplasia without atypia. The PALM-COEIN classification of abnormal uterine bleeding (AUB) categorises this patient’s cause under which structural category?","options":{"A":"Polyp (AUB-P)","B":"Adenomyosis (AUB-A)","C":"Leiomyoma (AUB-L)","D":"Endometrial (AUB-E)"},"page":90,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":237,"stem":"A 32-year-old woman who is breastfeeding her 8-week-old infant wishes to start contraception. She has a history of deep vein thrombosis. She prefers a highly effective, reversible, non-hormonal method that does not affect lactation. The BEST contraceptive option for her is:","options":{"A":"Copper intrauterine device (Cu-IUD)","B":"Combined oral contraceptive pill","C":"Levonorgestrel IUS (Mirena)","D":"Depot medroxyprogesterone acetate injection"},"page":90,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":238,"stem":"A couple presents with 2 years of primary infertility. Semen analysis: volume 2.5 mL, count 10 million/mL, motility 30","options":{"A":"Azoospermia","B":"Oligoasthenoteratozoospermia (OAT syndrome)","C":"Asthenospermia only","D":"Normospermia with female factor infertility"},"page":90,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":239,"stem":"A 29-year-old woman in active labour at 40 weeks has continuous electronic fetal monitoring. The CTG shows: baseline FHR 130 bpm, moderate variability (6–15 bpm), accelerations present, and variable decelerations (lasting 30–60 seconds, recovering to baseline). This CTG tracing is classified as:","options":{"A":"Normal/reassuring — no action needed","B":"Pathological — emergency delivery required","C":"Suspicious/non-reassuring — requires further evaluation","D":"Sinusoidal — immediate delivery"},"page":91,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":240,"stem":"A term neonate is delivered by emergency LSCS for fetal distress. At birth: no cry, floppy, cyanotic, HR 60 bpm, irregular gasping respirations. APGAR at 1 minute is 2. After drying, warming, and clearing the airway, what is the MOST appropriate NEXT step?","options":{"A":"Administer epinephrine IV immediately","B":"Perform cardiac compressions immediately","C":"Start positive pressure ventilation (PPV) with 100","D":"Intubate and give surfactant"},"page":91,"subject":"Obstetrics & Gynaecology","kind":"Concept / direct recall","section":"Surgery & Specialties"},{"n":241,"stem":"A 34-year-old woman at 32 weeks develops tonic-clonic convulsions at home. She was known to have BP 150/100 mmHg and 2+ proteinuria at her last visit. She is brought to hospital. BP now is 180/120 mmHg. The immediate priority is:","options":{"A":"Control seizures with IV magnesium sulphate and stabilise","B":"Emergency lower segment caesarean section immediately","C":"IV diazepam and observe for 24 hours","D":"Administer corticosteroids for fetal lung maturity first"},"page":91,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":242,"stem":"A 30-year-old primigravida at 33 weeks presents with epigastric pain, vomiting, and malaise. BP 155/105 mmHg. Investigations: haemoglobin 9.8 g/dL, platelet 62,000/µL, LDH 1,020 U/L, AST 185 U/L, peripheral smear shows schistocytes. This presentation is MOST consistent with:","options":{"A":"Acute fatty liver of pregnancy","B":"HELLP syndrome","C":"ITP (idiopathic thrombocytopenic purpura)","D":"Haemolytic uraemic syndrome"},"page":92,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":243,"stem":"A 24-year-old primigravida (O negative blood group) delivers a healthy Rh-positive baby. Which of the following is the MOST appropriate prophylactic measure to prevent Rh sensitisation in future pregnancies?","options":{"A":"Anti-D immunoglobulin 50 µg within 72 hours of delivery","B":"Anti-D immunoglobulin 300 µg within 72 hours of delivery","C":"Blood transfusion to the mother","D":"No action required as first pregnancy is usually safe"},"page":92,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":244,"stem":"A 22-year-old primigravida is in active labour. Cervical dilation is 5 cm with intact membranes. Uterine contractions are 3 in 10 minutes, each lasting 40 seconds. After 4 hours, repeat examination shows cervical dilation at 6 cm. Fetal descent has not changed. This pattern is MOST consistent with:","options":{"A":"Normal progress — Friedman’s curve shows this is acceptable","B":"Latent phase prolongation","C":"Precipitate labour","D":"Active phase arrest (failure to progress)"},"page":92,"subject":"Obstetrics & Gynaecology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":245,"stem":"A 15-month-old child is brought by parents concerned about developmental delay. On assessment: the child can walk independently, says 2– 3 words with meaning, uses a pincer grasp, and waves bye-bye. Which developmental milestone is appropriate for 15 months?","options":{"A":"Walking independently","B":"Saying full sentences of 4–5 words","C":"Drawing a triangle","D":"Riding a tricycle"},"page":92,"subject":"Obstetrics & Gynaecology","kind":"Concept / direct recall","section":"Surgery & Specialties"},{"n":246,"stem":"A term neonate (day 3 of life) has visible jaundice. Total serum bilirubin is 14 mg/dL; direct bilirubin 0.5 mg/dL. Baby is breastfeeding well, urine is clear yellow, stools are yellow. Blood group: mother O positive, baby A positive. DCT (direct Coombs test) is negative. The MOST likely diagnosis is:","options":{"A":"ABO incompatibility haemolytic disease","B":"Physiological jaundice of newborn","C":"Biliary atresia","D":"Breast milk jaundice"},"page":93,"subject":"Paediatrics","kind":"Concept / direct recall","section":"Surgery & Specialties"},{"n":247,"stem":"A 2-year-old child from a rural area has weight 7 kg (expected 12 kg for age). He has generalised oedema, moon face, flaky paint dermatosis, and flag sign in hair. Serum albumin is 1.8 g/dL. This clinical picture is MOST consistent with:","options":{"A":"Marasmus","B":"Marasmic-kwashiorkor","C":"Kwashiorkor","D":"Iron deficiency anaemia"},"page":93,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":248,"stem":"A 4-year-old child is brought with exertional dyspnoea and episodic cyanotic spells (hypercyanotic spells) that are relieved by squatting. On examination: systolic thrill at left sternal border, single S2, and an ejection systolic murmur. CXR shows boot-shaped heart (coeur en sabot) with decreased pulmonary vascular markings. The MOST likely diagnosis is: RV LV RA LA VSD Overriding Ao PS RVH TOF: Four Defects","options":{"A":"Ventricular septal defect (VSD) — isolated","B":"Transposition of great arteries (TGA)","C":"Atrial septal defect (ASD) — large","D":"Tetralogy of Fallot (TOF)"},"page":93,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":249,"stem":"A 6-week-old healthy infant is brought for immunisation. According to the Universal Immunisation Programme (UIP) of India, which vaccines are due at 6 weeks of age?","options":{"A":"OPV-1, Pentavalent-1 (DPT+HepB+Hib), RVV-1, PCV-1, fIPV-1","B":"OPV-0, BCG, Hepatitis B birth dose","C":"MMR-1 and Varicella","D":"OPV-3, Pentavalent-3, RVV-3"},"page":94,"subject":"Paediatrics","kind":"Concept / direct recall","section":"Surgery & Specialties"},{"n":250,"stem":"A 14-month-old child presents with 5 days of watery diarrhoea (8–10 stools/day). On examination: sunken eyes, reduced skin turgor, dry mucous membranes, HR 140/min, but no shock. The child is crying but consolable. This degree of dehydration is classified as moderate. The RECOMMENDED treatment according to WHO IMCI guidelines is: WHO ORS Composition (Low-Osmolarity) Sodium chloride: 2.6 g/L Trisodium citrate: 2.9 g/L Potassium chloride: 1.5 g/L Glucose anhydrous: 13.5 g/L Osmolarity: 245 mOsm/L","options":{"A":"IV Ringer’s lactate 100 mL/kg over 3 hours (Plan C)","B":"ORS 75 mL/kg over 4 hours in a health facility (Plan B)","C":"ORS at home, no monitoring needed (Plan A)","D":"Normal saline 20 mL/kg bolus stat then ORS"},"page":94,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":251,"stem":"A 2.5-year-old child develops a generalised tonic-clonic seizure lasting 2 minutes associated with fever of 39.5◦C. There is no neck stiffness or focal deficit. The seizure stops spontaneously. This is the first episode. The MOST appropriate NEXT step in management is:","options":{"A":"Lumbar puncture immediately to rule out meningitis","B":"Start long-term anticonvulsant therapy (phenobarbitone)","C":"Paracetamol for fever control, reassurance, and parental education","D":"MRI brain to exclude a structural cause"},"page":95,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":252,"stem":"A 4-year-old unvaccinated child presents with high fever, coryza, conjunctivitis, and Koplik’s spots on the buccal mucosa. Three days later, a maculopapular rash appears behind the ears and spreads downward. The MOST serious preventable complication of measles in malnourished children is:","options":{"A":"Otitis media","B":"Febrile convulsions","C":"Parotitis","D":"Pneumonia and/or encephalitis"},"page":95,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":253,"stem":"A 6-month-old unvaccinated infant presents with a 3-week history of paroxysmal cough followed by a high-pitched inspiratory whoop, posttussive vomiting, and apnoeic spells. WBC is 35,000/µL with 80","options":{"A":"Azithromycin","B":"Amoxicillin","C":"Co-trimoxazole","D":"Cephalexin"},"page":95,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":254,"stem":"A 6-month-old infant presents with poor feeding, failure to thrive, recurrent chest infections, and excessive sweating during feeds. On auscultation: harsh pansystolic murmur at the lower left sternal border, grade 4/6, with a mid-diastolic murmur at the apex. CXR shows cardiomegaly and increased pulmonary vascular markings. The MOST likely diagnosis is:","options":{"A":"ASD (atrial septal defect) — Ostium secundum","B":"Large VSD (ventricular septal defect) with left-to-right shunt","C":"PDA (patent ductus arteriosus)","D":"Pulmonary stenosis"},"page":96,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":255,"stem":"A 2-day-old neonate presents with lethargy, poor feeding, respiratory distress, and temperature instability (hypothermia 35.8◦C). Mother had prolonged rupture of membranes (28 hours). WBC is 3,200/µL (leukopenia), C-reactive protein 48 mg/L, blood culture is pending. The MOST common causative organism of early-onset neonatal sepsis in India is:","options":{"A":"Staphylococcus aureus","B":"Listeria monocytogenes","C":"Klebsiella pneumoniae","D":"Group B Streptococcus (GBS)"},"page":96,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":256,"stem":"A 5-year-old partially immunised child presents with low-grade fever, sore throat, and a thick, greyish-white membrane on the tonsils that bleeds on attempted removal. Bull neck appearance is noted. The child develops stridor. The MOST dangerous complication in the acute phase of diphtheria is:","options":{"A":"Parotitis","B":"Otitis media","C":"Peritonsillar abscess","D":"Laryngeal obstruction and myocarditis"},"page":96,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":257,"stem":"A 18-month-old child from a slum area presents with severe wasting, loose skin folds, prominent ribs, and an alert but anxious facial expression — \"old man’s face\". Weight is 55","options":{"A":"Grade III malnutrition (severe) — marasmus","B":"Grade II malnutrition (moderate) — kwashiorkor","C":"Grade I malnutrition (mild) — marasmic-kwashiorkor","D":"Normal nutritional status"},"page":97,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":258,"stem":"A preterm neonate (30 weeks gestation) at day 5 of life has increasing oxygen requirements and a continuous machine-like murmur best heard at the left upper sternal border/infraclavicular area. Echocardiography confirms PDA with significant left-to-right shunting. The drug of choice for pharmacological closure in a preterm neonate is:","options":{"A":"Furosemide","B":"Indomethacin or Ibuprofen (COX inhibitor)","C":"Digoxin","D":"Sildenafil"},"page":97,"subject":"Paediatrics","kind":"Concept / direct recall","section":"Surgery & Specialties"},{"n":259,"stem":"A 60-year-old man presents with gradual painless loss of peripheral vision. IOP by Goldmann applanation tonometry is 26 mmHg bilaterally. Gonioscopy shows open angles. Fundus examination shows cup-disc ratio 0.8 bilaterally with inferior notching of the neuroretinal rim. Visual field testing shows arcuate scotoma. The MOST likely diagnosis is: Inferior notch Disc Glaucomatous Optic Disc (CDR 0.8) Cup","options":{"A":"Acute angle-closure glaucoma","B":"Ocular hypertension without glaucoma","C":"Primary open-angle glaucoma (POAG)","D":"Secondary glaucoma from uveitis"},"page":97,"subject":"Paediatrics","kind":"Calculation / interpretation","section":"Surgery & Specialties"},{"n":260,"stem":"A 65-year-old man undergoes uncomplicated phacoemulsification with posterior chamber IOL implantation. Two months post-operatively he develops gradual painless blurring of vision. Slit-lamp examination shows posterior capsule opacity (PCO) — wrinkled posterior capsule with Elschnig’s pearls. The MOST appropriate treatment is:","options":{"A":"Repeat cataract surgery","B":"Topical corticosteroid eye drops for 6 weeks","C":"Anterior vitrectomy","D":"Nd:YAG laser posterior capsulotomy"},"page":98,"subject":"Paediatrics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":261,"stem":"A 50-year-old man with 15-year history of Type 2 DM presents with blurring of central vision. Fundoscopy shows: cotton wool spots, hard exudates within one disc diameter of the fovea, intraretinal microvascular abnormalities (IRMA), and venous beading — but no new vessels. This is classified as: Disc Macula Hard exudate CWS IRMA Venous bead Diabetic Retinopathy Stages Non-prol. DR: Mild/Mod/Severe Prolif. DR: NVD/NVE","options":{"A":"Severe non-proliferative diabetic retinopathy (NPDR)","B":"Mild NPDR","C":"Moderate NPDR","D":"Proliferative diabetic retinopathy (PDR)"},"page":98,"subject":"Ophthalmology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":262,"stem":"A 45-year-old myope presents with sudden onset of flashing lights (photopsia) and floaters followed by a dark curtain-like shadow progressing from the periphery toward the centre of vision. Visual acuity is 6/60 in the affected eye. Fundoscopy shows a grey, billowing retina with a break at the superotemporal quadrant. The MOST likely type of retinal detachment is:","options":{"A":"Exudative (secondary) retinal detachment","B":"Rhegmatogenous retinal detachment","C":"Tractional retinal detachment","D":"Retinoschisis"},"page":98,"subject":"Ophthalmology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":263,"stem":"A 3-year-old child from a tribal area presents with difficulty seeing in dim light. On examination, foamy, pearly-white triangular plaques are seen on the nasal and temporal conjunctiva bilaterally (Bitot’s spots). Cornea appears dry and lustreless. This condition is caused by deficiency of:","options":{"A":"Vitamin D","B":"Vitamin C","C":"Vitamin A","D":"Vitamin B12"},"page":99,"subject":"Ophthalmology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":264,"stem":"A 30-year-old contact lens wearer presents with a painful red eye, photophobia, and severe purulent discharge. Slit lamp shows a central corneal ulcer with dense stromal infiltrate and a hypopyon (2 mm). Corneal scraping Gram stain shows Gram-negative rods. The MOST appropriate treatment is:","options":{"A":"Topical antifungal (natamycin) hourly","B":"Topical acyclovir ointment 5 times daily","C":"Oral acyclovir and topical steroids","D":"Intensive topical fluoroquinolone (ciprofloxacin/moxifloxacin) hourly"},"page":99,"subject":"Ophthalmology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":265,"stem":"A 55-year-old woman with a pituitary macroadenoma on MRI develops progressive vision loss. Visual field testing (Goldmann perimetry) shows bitemporal hemianopia. The anatomical location of the lesion causing this defect is: L Eye R Eye Chiasm X X Bitemporal Hemianopia Lesion at optic chiasm","options":{"A":"Optic chiasm (compression by pituitary tumour)","B":"Right optic nerve","C":"Right optic tract","D":"Left occipital cortex"},"page":99,"subject":"Ophthalmology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":266,"stem":"A 28-year-old man with HLA-B27 positive ankylosing spondylitis presents with a painful, red eye with photophobia, lacrimation, and decreased vision. Slit-lamp examination: ciliary injection, keratic precipitates (fine, non-granulomatous), and posterior synechiae. The MOST likely diagnosis is:","options":{"A":"Acute conjunctivitis — bacterial","B":"Anterior uveitis (iridocyclitis)","C":"Posterior uveitis (choroiditis)","D":"Scleritis"},"page":100,"subject":"Ophthalmology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":267,"stem":"A 4-year-old child is brought with the left eye turning inward (esotropia) noted by parents. On the cover-uncover test, when the right eye is covered, the left eye (deviated eye) makes an outward movement to fix on the target. When the cover is removed, the left eye drifts inward again. The right eye does not move when the left is covered. This finding indicates:","options":{"A":"Paralytic (non-comitant) squint","B":"Intermittent squint of the right eye","C":"Unilateral concomitant squint (manifest esotropia of the left eye)","D":"Pseudosquint (epicanthal folds only)"},"page":100,"subject":"Ophthalmology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":268,"stem":"A 72-year-old woman presents with progressive central vision loss and distortion (metamorphopsia) in her right eye. On fundoscopy: multiple drusen deposits in the macular area, and an area of subretinal neovascular membrane with subretinal haemorrhage. OCT shows fluid under the neuroretinal layer. This is classified as:","options":{"A":"Dry (atrophic) ARMD — geographic atrophy","B":"Central serous retinopathy","C":"Macular hole","D":"Wet (neovascular/exudative) ARMD"},"page":101,"subject":"Ophthalmology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":269,"stem":"A 5-year-old child presents with right earache, fever (39◦C), and decreased hearing for 3 days after an upper respiratory tract infection. On otoscopy: right tympanic membrane is bulging, red, and opaque with loss of cone of light and landmarks. The MOST appropriate initial treatment for acute suppurative otitis media is: Cone of light Posterosup. Anterosup. Posteroinf. Anteroinf. Malleus Tympanic Membrane Quadrants (Right)","options":{"A":"Amoxicillin for 5–7 days plus analgesics","B":"Myringotomy and grommet insertion","C":"Topical antibiotic ear drops only","D":"Immediate mastoidectomy"},"page":101,"subject":"Ophthalmology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":270,"stem":"A 45-year-old man presents with progressive hearing loss in the right ear following a road traffic accident with head injury. On tuning fork tests (512 Hz): Rinne’s test is AC < BC (Rinne’s negative) on the right; Weber’s test lateralises to the right ear. This pattern is MOST consistent with:","options":{"A":"Sensorineural hearing loss in the right ear","B":"Conductive hearing loss in the right ear","C":"Sensorineural hearing loss in the left ear","D":"Mixed hearing loss bilaterally"},"page":101,"subject":"Ophthalmology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":271,"stem":"An audiogram of a 55-year-old man who works in a noisy factory shows: Air conduction thresholds elevated bilaterally (worst at 4000 Hz — a notch pattern), bone conduction thresholds mirror image of air conduction with no air-bone gap. Speech discrimination is poor. The MOST likely diagnosis is: Hz dB HL 1k 2k 4k AC BC NIHL Audiogram: 4kHz Notch","options":{"A":"Otosclerosis","B":"Age-related hearing loss (presbycusis)","C":"Noise-induced hearing loss (NIHL)","D":"Meniere’s disease"},"page":102,"subject":"ENT","kind":"Visual / interpretation","section":"Surgery & Specialties"},{"n":272,"stem":"A 35-year-old man presents with a 10-year history of foul-smelling, scanty, unilateral ear discharge. He now develops headache and swelling behind the right ear (mastoid). On otoscopy: retraction pocket in the posterior superior quadrant with white pearly mass and a marginal perforation. CT mastoid shows bone erosion. The MOST likely complication of untreated cholesteatoma is:","options":{"A":"Serous otitis media","B":"Eustachian tube dysfunction","C":"Tympanosclerosis","D":"Intracranial extension — meningitis or brain abscess"},"page":102,"subject":"ENT","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":273,"stem":"A 38-year-old man with known bronchial asthma and aspirin sensitivity presents with bilateral nasal blockage, anosmia, and clear rhinorrhoea for 2 years. Anterior rhinoscopy reveals pale, gelatinous masses in both nasal cavities originating from the middle meatus. The drug of choice for nasal polyps is:","options":{"A":"Topical intranasal corticosteroids (e.g., mometasone)","B":"Systemic antihistamines","C":"Antibiotic (amoxicillin-clavulanate) for 6 weeks","D":"Topical decongestant (oxymetazoline) long term"},"page":103,"subject":"ENT","kind":"Calculation / interpretation","section":"Surgery & Specialties"},{"n":274,"stem":"A 25-year-old man presents with spontaneous left-sided anterior epistaxis. The bleeding point is identified on the anteroinferior nasal septum (Little’s area / Kiesselbach’s plexus). He is haemodynamically stable. The MOST appropriate initial management is:","options":{"A":"Posterior nasal packing with Foley catheter balloon","B":"Compression of the soft part of the nose for 10–20 minutes and chemical cauterisation with silver nitrate","C":"Urgent embolisation of the internal maxillary artery","D":"IV tranexamic acid and blood transfusion"},"page":103,"subject":"ENT","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":275,"stem":"A 10-year-old child with acute frontal sinusitis develops progressive proptosis, oedema and erythema of the eyelids, restricted ocular motility, and fever. CT orbit shows a collection between the periorbita and orbital walls. The MOST likely complication is:","options":{"A":"Pre-septal (periorbital) cellulitis","B":"Cavernous sinus thrombosis","C":"Subperiosteal abscess of the orbit","D":"Mucocele of the frontal sinus"},"page":103,"subject":"ENT","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":276,"stem":"A 62-year-old male smoker (40 pack-years) presents with hoarseness of voice for 6 months, now with dysphagia and right neck lymph node enlargement. Indirect laryngoscopy shows an irregular growth on the right true vocal cord extending to the supraglottis. Biopsy confirms squamous cell carcinoma. This tumour (supraglottic) has which lymphatic drainage making early nodal spread possible?","options":{"A":"No lymphatic drainage (glottis)","B":"Sparse lymphatic drainage — late metastasis","C":"Drains to submental nodes","D":"Rich bilateral lymphatic drainage to deep cervical nodes"},"page":104,"subject":"ENT","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":277,"stem":"A 50-year-old man is admitted to the ICU following Guillain-Barré syndrome with progressive respiratory failure. He has been intubated for 14 days. The team is considering tracheostomy. The MOST important indication for tracheostomy in this scenario is:","options":{"A":"Prolonged mechanical ventilation requiring long-term airway access","B":"Acute upper airway obstruction only","C":"To facilitate oral feeding","D":"Laryngeal tumour resection"},"page":104,"subject":"ENT","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":278,"stem":"A 2-year-old child is brought to the emergency department with sudden onset choking, coughing, and stridor after playing with peanuts. He is conscious, able to cry, and has partial airway obstruction. The MOST appropriate immediate manoeuvre for a conscious child with partial airway obstruction is:","options":{"A":"Blind finger sweep in the mouth","B":"5 back blows alternating with 5 chest thrusts (for child >1 year: abdominal thrusts after back blows)","C":"Emergency tracheostomy","D":"Immediate rigid bronchoscopy in the ED"},"page":104,"subject":"ENT","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":279,"stem":"A 25-year-old motorcyclist sustains a twisting injury to the right tibia. Xray shows a fracture line that spirals around the bone shaft at an oblique angle over a long segment. This type of fracture is classified as: Transverse Spiral Comminuted Fracture Types","options":{"A":"Transverse fracture","B":"Comminuted fracture","C":"Spiral fracture","D":"Greenstick fracture"},"page":105,"subject":"ENT","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":280,"stem":"A 28-year-old man with closed fracture of the right femur develops, 48 hours after conservative management, acute confusion, dyspnoea (SpO2","options":{"A":"Pulmonary thromboembolism","B":"ARDS from sepsis","C":"Haemothorax from rib fractures","D":"Fat embolism syndrome (Gurd’s criteria)"},"page":105,"subject":"ENT","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":281,"stem":"A 55-year-old osteoporotic woman falls on an outstretched hand. She presents with a dinner-fork deformity of the right wrist, pain, and swelling. X-ray shows a fracture of the distal radius with dorsal displacement, dorsal angulation, radial deviation, and impaction. This is MOST consistent with:","options":{"A":"Colles’ fracture","B":"Smith’s fracture","C":"Barton’s fracture","D":"Monteggia fracture-dislocation"},"page":105,"subject":"Orthopaedics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":282,"stem":"A 16-year-old boy presents with progressive pain and swelling around the left knee for 3 months. X-ray shows a destructive lesion in the distal femur metaphysis with periosteal reaction (Codman’s triangle and sunburst pattern) and soft tissue extension. Serum ALP is markedly elevated. Biopsy shows malignant osteoid production. The MOST likely diagnosis is:","options":{"A":"Giant cell tumour of bone","B":"Osteosarcoma","C":"Ewing’s sarcoma","D":"Chondrosarcoma"},"page":106,"subject":"Orthopaedics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":283,"stem":"A 19-year-old man sustains a closed fracture of the right tibial shaft managed in a plaster cast. Three hours later he develops severe unrelenting pain, worse on passive stretching of the toes, with a tense swollen leg, paraesthesia in the foot, and pallor. Compartment pressure is 45 mmHg (diastolic BP - compartment pressure < 30 mmHg). The MOST appropriate treatment is:","options":{"A":"Elevate the limb and administer IV morphine","B":"Apply ice packs and observe for 4 hours","C":"Emergency fasciotomy of all four compartments of the leg","D":"Urgent angiography to rule out vascular injury"},"page":106,"subject":"Orthopaedics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":284,"stem":"A 45-year-old man on long-term high-dose prednisolone for SLE presents with progressive right hip pain and limited range of movement over 8 months. MRI right hip shows a subchondral crescent sign and collapse of the femoral head. The MOST likely diagnosis is:","options":{"A":"Osteoarthritis of the hip","B":"Septic arthritis","C":"Rheumatoid arthritis","D":"Avascular necrosis (AVN) of the femoral head"},"page":106,"subject":"Orthopaedics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":285,"stem":"A 10-year-old boy presents with a 5-day history of fever, exquisite tenderness, and swelling over the proximal tibia. He refuses to weight-bear. WBC is 18,000/µL, ESR 80 mm/hr, CRP 95 mg/L. X-ray shows periosteal elevation after 10 days. The MOST common causative organism of acute haematogenous osteomyelitis in this age group is:","options":{"A":"Staphylococcus aureus","B":"Streptococcus pyogenes","C":"Salmonella typhi","D":"Pseudomonas aeruginosa"},"page":107,"subject":"Orthopaedics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":286,"stem":"A 30-year-old man sustains a fracture of the mid-shaft humerus in a road traffic accident. Following plaster cast application, he develops wrist drop and inability to extend the fingers at the metacarpophalangeal joints. Sensation is impaired over the dorsum of the hand and thumb web space. The MOST likely nerve injured is: Seddon Classification of Nerve Injuries Neuropraxia Axonotmesis Neurotmesis Conduction block only Axon disrupted Endoneurium intact Complete nerve division Full recovery Recovery possible No spontaneous recovery Weeks Months Surgery needed","options":{"A":"Median nerve","B":"Radial nerve","C":"Ulnar nerve","D":"Musculocutaneous nerve"},"page":107,"subject":"Orthopaedics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":287,"stem":"A 22-year-old man falls on an outstretched abducted, externally rotated arm. He presents with the arm held in abduction and external rotation, loss of shoulder contour, and a palpable fullness in the axilla. He cannot internally rotate or adduct the arm. The MOST common type of shoulder dislocation is:","options":{"A":"Posterior dislocation","B":"Inferior dislocation (luxatio erecta)","C":"Anterior glenohumeral dislocation","D":"Superior dislocation"},"page":107,"subject":"Orthopaedics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":288,"stem":"A 14-year-old boy presents with pain, swelling, and fever over the midshaft of the right femur. X-ray shows a permeative destructive lesion in the diaphysis with multilayered periosteal reaction (onion-skin appearance) and a soft tissue mass. ESR and LDH are elevated. The MOST likely diagnosis is:","options":{"A":"Osteosarcoma","B":"Acute osteomyelitis","C":"Giant cell tumour","D":"Ewing’s sarcoma"},"page":108,"subject":"Orthopaedics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":289,"stem":"During a pre-operative anaesthetic assessment, a 45-year-old obese woman opens her mouth maximally and protrudes her tongue. The anaesthetist can see only the soft palate with no uvula or faucial pillars visible. According to Mallampati classification, this is:","options":{"A":"Class III (difficult intubation predicted)","B":"Class I (easy intubation)","C":"Class II (moderate difficulty)","D":"Class IV (impossible intubation without adjuncts)"},"page":108,"subject":"Orthopaedics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":290,"stem":"A 35-year-old healthy woman is scheduled for elective laparoscopic cholecystectomy under general anaesthesia. The surgeon requests intraperitoneal CO2 insufflation to 14 mmHg. Considering the risk of aspiration, which airway device is PREFERRED?","options":{"A":"Laryngeal mask airway (LMA) — supraglottic device","B":"Endotracheal tube (ETT) with cuffed tube for airway protection","C":"Nasopharyngeal airway only","D":"Oropharyngeal airway (Guedel) only"},"page":108,"subject":"Orthopaedics","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":291,"stem":"A 28-year-old woman undergoes laparoscopic gynaecological surgery under general anaesthesia with opioids and nitrous oxide. In the recovery room she develops severe nausea and vomiting (PONV). Her Apfel PONV risk score is 4 (female sex, non-smoker, history of PONV, opioid use). The FIRST-LINE antiemetic recommended for PONV prophylaxis in high-risk patients is:","options":{"A":"Haloperidol IV","B":"Metoclopramide IV","C":"Ondansetron IV (5HT3 antagonist)","D":"Promethazine IM"},"page":109,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":292,"stem":"A 60-year-old man undergoes elective open abdominal aortic aneurysm repair. Post-operatively he is expected to have severe pain. The anaesthetist plans multimodal analgesia. Which of the following regional anaesthesia techniques provides the BEST post-operative analgesia for open abdominal surgery?","options":{"A":"Femoral nerve block","B":"IV morphine PCA alone","C":"Intercostal nerve block at one level","D":"Epidural analgesia (thoracic epidural catheter)"},"page":109,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":293,"stem":"A 40-year-old man presents with sudden-onset severe abdominal pain and guarding. An erect chest X-ray is performed. The radiological sign that MOST specifically indicates a perforated hollow viscus on erect CXR is:","options":{"A":"Air under the right hemidiaphragm (Pneumoperitoneum)","B":"Air-fluid levels in the colon only","C":"Double bubble sign","D":"Sail sign"},"page":109,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":294,"stem":"A 2-week-old neonate presents with cyanosis, tachypnoea, and poor feeding from birth. CXR shows a figure-of-8 or snowman-shaped cardiac silhouette. The MOST likely diagnosis associated with this X-ray finding is:","options":{"A":"Tetralogy of Fallot","B":"Total anomalous pulmonary venous connection (TAPVC) — supracardiac type","C":"Transposition of the great arteries","D":"Coarctation of the aorta"},"page":110,"subject":"Anaesthesiology","kind":"Visual / interpretation","section":"Surgery & Specialties"},{"n":295,"stem":"A neonate born to a mother with polyhydramnios presents with bilious vomiting from the first feed. AXR shows two gas-filled bubbles (stomach + proximal duodenum) with no distal bowel gas. Down syndrome features are noted on examination. The MOST likely diagnosis is:","options":{"A":"Pyloric stenosis","B":"Jejunal atresia","C":"Duodenal atresia","D":"Malrotation with midgut volvulus"},"page":110,"subject":"Anaesthesiology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":296,"stem":"A 55-year-old man is undergoing CT pulmonary angiography with IV iodinated contrast. Within 5 minutes he develops urticaria, facial oedema, stridor, and hypotension (BP 80/50 mmHg). This is classified as a severe anaphylactoid contrast reaction. The MOST appropriate IMMEDIATE treatment is:","options":{"A":"IV hydrocortisone 200 mg and IV antihistamine","B":"IV normal saline bolus alone","C":"Oral prednisolone and observe","D":"IM adrenaline (epinephrine) 0.5 mg (1:1000) and IV fluid resuscitation"},"page":110,"subject":"Radiology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":297,"stem":"A 2-year-old child with acute respiratory illness has a CXR showing thymic enlargement with a triangular opacity in the right upper mediastinum with a wavy lateral border (also called thymic wave sign). This radiological sign in children is known as:","options":{"A":"Sail sign (thymic sail sign)","B":"Hampton’s hump","C":"Westermark’s sign","D":"Air bronchogram sign"},"page":111,"subject":"Radiology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":298,"stem":"A 50-year-old man presents with progressive jaundice, dark urine, pale stools, and weight loss of 5 kg over 2 months. He has no pain. On examination: deep jaundice, palpable non-tender gallbladder. Investigations: total bilirubin 22 mg/dL (predominantly conjugated), ALP 850 U/L, ALT 120 U/L, CA 19-9 markedly elevated. CT scan shows a mass in the head of the pancreas. The MOST appropriate surgical procedure for potentially curable disease is:","options":{"A":"Whipple’s procedure (pancreaticoduodenectomy)","B":"Distal pancreatectomy with splenectomy","C":"Billroth II gastrectomy","D":"ERCP with stenting only (palliative)"},"page":111,"subject":"Radiology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":299,"stem":"A 65-year-old hypertensive smoker presents with sudden severe tearing chest pain radiating to the back between the shoulder blades, unequal blood pressures in both arms (right 170 mmHg, left 120 mmHg), and aortic regurgitation murmur on auscultation. ECG shows no ST changes. The MOST appropriate investigation to confirm the diagnosis urgently is:","options":{"A":"ECG and troponin levels","B":"CT angiography of the aorta (CT aortogram)","C":"Coronary angiography","D":"Transthoracic echocardiography alone"},"page":111,"subject":"Radiology","kind":"Clinical vignette","section":"Surgery & Specialties"},{"n":300,"stem":"A 70-year-old man with known diabetes presents from the emergency department with fever (40◦C), confusion, HR 130/min, BP 80/50 mmHg, respiratory rate 28/min, SpO2 90","options":{"A":"CT abdomen first to identify the source before antibiotics","B":"Administer norepinephrine and monitor for 2 hours","C":"Obtain central venous access and monitor CVP","D":"IV broad-spectrum antibiotics within 1 hour + IV fluid resuscitation + oxygen"},"page":112,"subject":"Medicine","kind":"Clinical vignette","section":"Surgery & Specialties"}]};
